/**
 * The band above the prompt: the switch for the pane, and what needs a person.
 *
 * The pane is opened by a press here rather than by a typed command, and that
 * is the reason the band exists at all: a command typed while a turn runs waits
 * for the turn to end, and a press on a band button runs at once. So the switch
 * is always drawn, whatever the fleet holds.
 *
 * Beside it the band states the fleet in one line: how many sessions work and
 * wait, how many outcomes failed, and the worst thing that needs a person, with
 * the rest counted after it. Errors sort ahead of waits, so the first item is
 * the worst. This session's own job is left out, because a session telling its
 * own person that it is working is noise, and so is anything the person
 * dismissed.
 *
 * Beside the fleet's switch sits the voice's. Speech is one switch for every
 * session on the machine, so the word on it is what the store says, and a press
 * in any session is heard in all of them. Beside the voice sits the machine's
 * governance switch when the machine has one: it states both scopes in a word
 * and moves them together, and it is not drawn at all for a person who does not
 * run the tooling behind it. Each button carries an icon: a glyph a terminal
 * draws in one cell where the surface is a terminal, and an emoji where the
 * surface draws pictures.
 */

import type { Color, Node } from "./host.ts";
import { chip } from "./cards.ts";
import { box, fit, pressable, text } from "./layout.ts";
import { mask } from "./mask.ts";
import { active, failedOutcomes, waiting, working } from "./pane.ts";
import type { Job, Snapshot } from "./state.ts";

/** The address of the band's switch, which is what a press comes back on. */
export const BAND_TOGGLE = "fleet.band.toggle";
/** The address of the button that hides what the band is showing. */
export const BAND_DISMISS = "fleet.band.dismiss";
/** The address of the switch that turns speech on or off in every session. */
export const BAND_SPEAK = "fleet.band.speak";
/** The address of the machine's governance switch, when the machine has one. */
export const BAND_GOVERNANCE = "fleet.band.governance";
/** The address of pacer's switch, which takes the gear on a machine that runs pacer. */
export const BAND_PACER = "fleet.band.pacer";
/** The address of a press on one of the band's figures, before the state it names. */
export const BAND_FOCUS = "fleet.band.focus.";
/** The address of a press on the item the band leads with. */
export const BAND_ITEM = "fleet.band.item.";

/** The cell the rule above the buttons is drawn from, written as a code point. */
const BAND_RULE = "─";

/** The icon each switch carries, as a terminal draws it and as a picture surface does. */
const ICONS = {
  terminal: { fleet: "\u2261", speaking: "\u266A", quiet: "\u266A", governance: "\u2699" },
  pictures: { fleet: "\u{1F4CB}", speaking: "\u{1F50A}", quiet: "\u{1F507}",
              governance: "\u2699\ufe0f" },
} as const;

function icons(surface: string | undefined) {
  return surface === undefined || surface === "terminal" ? ICONS.terminal : ICONS.pictures;
}

/**
 * The fleet switch's word, which says which way a press goes, after its icon;
 * `short` keeps the icon and the verb alone, for a band too narrow for the
 * product's name.
 */
export function fleetLabel(open: boolean, surface?: string, short = false): string {
  const word = short ? (open ? "Close" : "Open") : (open ? "Close llm-fleet" : "Open llm-fleet");
  return icons(surface).fleet + " " + word;
}

/**
 * The speech switch's word, which says how speech stands in every session,
 * after its icon; `short` keeps the icon and the state alone, for a narrow band.
 */
export function speakLabel(speaking: boolean, surface?: string, short = false): string {
  const set = icons(surface);
  const word = short ? "" : "Speak: ";
  return speaking ? set.speaking + " " + word + "on" : set.quiet + " " + word + "off";
}

/**
 * The governance switch's word, after its icon: one word for two scopes, so the
 * band stays one line. A scope the switch did not report is "not read" rather
 * than folded into either answer.
 */
export function governanceLabel(governor: boolean | null, controller: boolean | null,
                                surface?: string, short = false): string {
  const word = governor === true && controller === true ? "on"
    : governor === false && controller === false ? "off"
    : governor === null || controller === null ? "not read" : "mixed";
  return icons(surface).governance + " " + (short ? "" : "Gov ") + word;
}

/**
 * Pacer's switch word, after the gear: on, off, or not read when pacer did not
 * say, and "off?" while a first press to switch it off waits for the second.
 */
export function pacerLabel(enabled: boolean | null, surface?: string, short = false,
                           confirming = false): string {
  const word = enabled === true ? (confirming ? "off?" : "on")
    : enabled === false ? "off" : "not read";
  return icons(surface).governance + " " + (short ? "" : "Pacer ") + word;
}

/** One thing the band can lead with, under a key that names it across readings. */
export type BandItem = {
  key: string;
  level: "error" | "warning";
  text: string;
};

/** The figures the band states, or null when there is no reading to state them from. */
export type BandCounts = { working: number; waiting: number; failed: number };

/**
 * Whether a job is this session's own.
 *
 * A job's id is the head of its session's identifier, and a job may carry the
 * whole identifier too; either one matching is the same session.
 */
export function isOwnJob(job: Job, sessionId: string): boolean {
  if (!sessionId) {
    return false;
  }
  if (job.session_id && job.session_id === sessionId) {
    return true;
  }
  return job.id !== "" && sessionId.startsWith(job.id);
}

/** What a value says once anything secret in it is masked. */
function said(value: string | null | undefined): string {
  return mask(value ?? "").text;
}

/** What the band shows and keeps, as the reading carries it. */
export type BandConfig = {
  /** How many dismissed keys are kept: the newest. */
  hiddenLimit: number;
  /** How long after a job blocked it still leads the band rather than waiting in the pane. */
  waitingJobSeconds: number;
};

/** The schema's defaults, for a reading that carries no band document or an unusable value. */
export const BAND_DEFAULTS: BandConfig = { hiddenLimit: 200, waitingJobSeconds: 86_400 };

/** The band settings a reading carries, each one the default when it is not a whole number above nought. */
export function bandConfigFrom(documents: unknown): BandConfig {
  const carried = (documents as { band?: Record<string, unknown> } | null)?.band;
  if (typeof carried !== "object" || carried === null) {
    return BAND_DEFAULTS;
  }
  const whole = (key: keyof BandConfig): number => {
    const value = carried[key];
    return typeof value === "number" && Number.isInteger(value) && value >= 1
      ? value : BAND_DEFAULTS[key];
  };
  return { hiddenLimit: whole("hiddenLimit"), waitingJobSeconds: whole("waitingJobSeconds") };
}

/**
 * The dismissal limit a reading carries, or null when it carries none.
 *
 * Unlike `bandConfigFrom`, no default stands in: a reading without a limit says
 * nothing about how many dismissals to keep, so it is no reason to cut them.
 */
export function hiddenLimitFrom(documents: unknown): number | null {
  const carried = (documents as { band?: Record<string, unknown> } | null)?.band;
  const value = typeof carried === "object" && carried !== null ? carried.hiddenLimit : undefined;
  return typeof value === "number" && Number.isInteger(value) && value >= 1 ? value : null;
}

/** The source each kind of band item comes from, by the head of its key. */
const KEY_SOURCES: Record<string, string> = {
  job: "roster", trial: "trials", run: "progress", pr: "prs", skill: "skills", pacer: "pacer",
};

/** The source a band key belongs to, or null for a key no source makes. */
function keySource(key: string): string | null {
  return KEY_SOURCES[key.slice(0, key.indexOf(":"))] ?? null;
}

/**
 * The sources that answered this reading: read ready or empty, with no error.
 *
 * Only such a source can say an item has gone. A roster with one provider
 * failing is ready with an error, and that provider's jobs are absent only
 * because nobody could ask.
 */
export function answeredSources(snapshot: Snapshot): Set<string> {
  const answered = new Set<string>();
  for (const name of Object.values(KEY_SOURCES)) {
    // A reading taken before a source existed carries no document for it, and
    // such a source has not answered.
    const document = snapshot[name as keyof Snapshot] as
      { state?: string; errors?: unknown[] } | undefined;
    if (document === undefined) {
      continue;
    }
    if ((document.state === "ready" || document.state === "empty")
        && (document.errors ?? []).length === 0) {
      answered.add(name);
    }
  }
  return answered;
}

/**
 * The dismissed keys to keep once a dismissal is written.
 *
 * A key that names nothing the band could show now is dropped, since it hides
 * nothing, but only when its source answered this reading: an item absent
 * because its source failed is still dismissed when the source recovers. The
 * keys just dismissed go last, each kept once, and only the newest `limit` are
 * kept. Without `answered`, every source is taken to have answered.
 */
export function keptHidden(hidden: readonly string[], current: readonly string[],
                           dismissing: readonly string[], limit: number,
                           answered: ReadonlySet<string> | null = null): string[] {
  const live = new Set(current);
  const fresh = new Set(dismissing);
  const unasked = (key: string): boolean => {
    const source = keySource(key);
    return answered !== null && source !== null && !answered.has(source);
  };
  const kept = hidden.filter((key) => (live.has(key) || unasked(key)) && !fresh.has(key));
  return [...new Set([...kept, ...dismissing])].slice(-limit);
}

/** What a new skill finding says on the band, and whether it is an error or a wait. */
function skillItem(skill: Snapshot["skills"]["new"][number]): BandItem {
  const key = "skill:" + skill.target + ":" + skill.verdict + ":" + skill.hash;
  if (skill.verdict === "flagged") {
    return { key, level: "error",
             text: "Skill flagged: " + said(skill.name) + ", " + said(skill.issue) };
  }
  if (skill.verdict === "failed") {
    return { key, level: "warning", text: "Skill scan could not finish: " + said(skill.name) };
  }
  return { key, level: "warning",
           text: "Skill to read: " + said(skill.name) + ", " + said(skill.issue) };
}

/** Change states after which a failed trial no longer needs anybody. */
const SETTLED_CHANGES = new Set(["MERGED", "CLEANED"]);

/**
 * Everything in a reading that needs a person, worst first.
 *
 * A failed trial on a change still open, a run with failures, a pull request
 * whose checks fail and a newly flagged skill are errors; a session waiting on
 * its person, and a new skill finding to read or a scan that could not finish,
 * are waits. The key of each carries what makes it the same item next time, so
 * a dismissed item stays hidden until it changes: a session that waits a second
 * time is a new item.
 *
 * A job that blocked longer ago than `waitingJobSeconds` is parked rather than
 * waiting on its person now, so it stays in the pane and off the band; the age
 * is read against `now`, or against the reading's own clock without one. A job
 * no read has dated is kept, since nothing shows it to be parked.
 */
export function bandItems(snapshot: Snapshot, dismissed: readonly string[],
                          sessionId: string,
                          settings: BandConfig & { now?: number } = BAND_DEFAULTS): BandItem[] {
  const hidden = new Set(dismissed);
  const errors: BandItem[] = [];
  const waits: BandItem[] = [];
  const now = settings.now ?? snapshot.generated_at;
  for (const trial of snapshot.trials.recent) {
    if (!trial.is_green && !SETTLED_CHANGES.has(trial.change_state)) {
      errors.push({ key: "trial:" + trial.key, level: "error",
                    text: "Trial failed on " + said(trial.repo) + " " + said(trial.branch) + ": "
                      + (trial.failed + trial.errors) + " failed" });
    }
  }
  for (const run of snapshot.progress.runs) {
    if (run.failed > 0) {
      errors.push({ key: "run:" + run.key + ":" + run.failed, level: "error",
                    text: said(run.label || run.display) + ": " + run.failed + " failed" });
    }
  }
  // A run pacer refused, or one that failed while pacer held its slot. A run
  // made with pacing off failed on its own terms and is not pacer's to raise,
  // and one the person stopped did not fail.
  for (const run of snapshot.pacer?.recent ?? []) {
    const refused = run.mode === "refused";
    if (!refused && (run.exit === 0 || run.mode === "off" || run.mode === "interrupted")) {
      continue;
    }
    const where = said(run.repo ?? "a repository");
    errors.push({ key: "pacer:" + (run.repo ?? "") + ":" + run.at, level: "error",
                  text: refused
                    ? "Pacer refused a run in " + where + (run.reason ? ": " + said(run.reason) : "")
                    : "Run failed in " + where + ": exit " + run.exit });
  }
  for (const pull of snapshot.prs.prs) {
    if (pull.checks === "fail") {
      errors.push({ key: "pr:" + pull.repo + "#" + (pull.number ?? "") + ":" + pull.head,
                    level: "error",
                    text: "PR " + (pull.number === null ? "" : pull.number + " ")
                      + "checks failing: " + said(pull.title) });
    }
  }
  for (const skill of snapshot.skills.new) {
    const item = skillItem(skill);
    (item.level === "error" ? errors : waits).push(item);
  }
  for (const job of snapshot.roster.jobs) {
    const dated = job.since !== null && job.since !== undefined;
    if (dated && now - (job.since as number) > settings.waitingJobSeconds) {
      continue;
    }
    if (waiting(job) && !isOwnJob(job, sessionId)) {
      const since = dated ? ":" + Math.trunc(job.since as number) : "";
      waits.push({ key: "job:" + job.id + ":blocked" + since, level: "warning",
                   text: said(job.name) + " is waiting for you" });
    }
  }
  return [...errors, ...waits].filter((item) => !hidden.has(item.key));
}

/**
 * The figures the band states, counted the way the pane's head counts them,
 * less this session's own job: the band leaves that job out of its items, and a
 * figure that counted it would say "1 waiting" beside nothing that waits.
 */
export function bandCounts(snapshot: Snapshot, sessionId = ""): BandCounts | null {
  if (snapshot.roster.state !== "ready") {
    return null;
  }
  const jobs = snapshot.roster.jobs.filter((job) => !isOwnJob(job, sessionId));
  return {
    working: jobs.filter((job) => working(job) || active(job)).length,
    waiting: jobs.filter(waiting).length,
    failed: failedOutcomes(snapshot),
  };
}

export type BandInput = {
  /** What needs a person, worst first; empty when nothing does. */
  items: BandItem[];
  /** The figures, or null while there is no reading or the roster could not be read. */
  counts: BandCounts | null;
  /** Why there are no figures, when that is the case, such as a read in flight. */
  note?: string;
  /** Whether the pane is open, which is what the switch's word says. */
  open: boolean;
  /** The cells the band is laid out in. */
  width: number;
  /** The surface drawing the band, which picks the icons; a terminal when absent. */
  surface?: string;
  /** Whether speech is on in every session; the speech switch is drawn only with `onSpeak`. */
  speaking?: boolean;
  /**
   * The machine's governance switch, drawn only when the machine has one: a
   * reading whose source is unconfigured says nothing here and the button goes.
   */
  governance?: { governor: boolean | null; controller: boolean | null } | null;
  onToggle: () => unknown;
  onDismiss: () => void;
  onSpeak?: () => unknown;
  onGovernance?: () => unknown;
  /**
   * Pacer's switch, drawn only on a machine that runs pacer, where it takes
   * the gear in place of the governance switch it replaces.
   */
  pacer?: { enabled: boolean | null; confirming?: boolean } | null;
  onPacer?: () => unknown;
  /**
   * Open the pane, narrowed to one of the figures, or to the whole fleet.
   *
   * The band is on screen while the pane is shut, which is when a person reads
   * a count and wants the rows behind it; without this the figure is a number
   * they have to go and find.
   */
  /**
   * The press that opens the pane, as this session's state to start it in.
   *
   * A figure names a state, and the pane opens narrowed to it. The item a band
   * leads with names a row instead, so it hands its key over and the pane opens
   * on the section that row lives in, the rest folded out of the way.
   */
  onOpen?: (focus?: "working" | "waiting" | "failed", key?: string) => unknown;
};

/** The cells a button adds around its label: "[ " before it and " ]" after. */
const BUTTON_CHROME = 4;
/** The cells between two parts of the band's line. */
const PART_GAP = 2;

/** One button, as the host draws a press: the address it comes back on, and its word. */
function button(key: string, label: string, onPress: () => unknown, primary = false): Node {
  return { type: "Button",
           props: { key, label, onPress, ...(primary ? { variant: "primary" as const } : {}) },
           children: [] };
}

/**
 * The band's one line.
 *
 * The switch leads, so it sits in the same place whatever else the line holds.
 * The figures follow on chips, a figure at zero left out, and then the worst
 * item in its own color with the rest counted after it. Dismiss is offered only
 * when there is something to dismiss. A line too long for the band is cut from
 * the item's end, never from the switch or the figures.
 */
export function bandTree(input: BandInput): Node {
  const toggle = fleetLabel(input.open, input.surface);
  const parts: Node[] = [button(BAND_TOGGLE, toggle, input.onToggle, !input.open)];
  // What the line takes as the terminal draws it: a button is its label in
  // "[ " and " ]", a chip is its word with a cell of fill at each side, and
  // every part after the first sits two cells from the one before.
  let used = toggle.length + BUTTON_CHROME;
  if (input.onSpeak !== undefined) {
    const speaking = input.speaking === true;
    const word = speakLabel(speaking, input.surface);
    parts.push(button(BAND_SPEAK, word, input.onSpeak, speaking));
    used += PART_GAP + word.length + BUTTON_CHROME;
  }
  // The machine's switch sits beside the voice's, and only while the machine
  // has one: a person who does not run that tooling never sees the button.
  // Pacer takes the gear where it runs; the governance switch it replaces is
  // drawn only on a machine without pacer.
  const pacing = input.pacer !== undefined && input.pacer !== null
    && input.onPacer !== undefined;
  const governing = !pacing && input.governance !== undefined && input.governance !== null
    && input.onGovernance !== undefined;
  const gear: { key: string; press: () => unknown; label: (short: boolean) => string } | null =
    pacing ? { key: BAND_PACER, press: input.onPacer as () => unknown,
               label: (short) => pacerLabel(input.pacer?.enabled ?? null, input.surface, short,
                                            input.pacer?.confirming === true) }
    : governing ? { key: BAND_GOVERNANCE, press: input.onGovernance as () => unknown,
                    label: (short) => governanceLabel(input.governance?.governor ?? null,
                                                      input.governance?.controller ?? null,
                                                      input.surface, short) }
    : null;
  let gearAt = -1;
  if (gear !== null) {
    const word = gear.label(false);
    gearAt = parts.length;
    parts.push(button(gear.key, word, gear.press));
    used += PART_GAP + word.length + BUTTON_CHROME;
  }
  const figures: [number, string, Color, "working" | "waiting" | "failed"][] =
    input.counts === null ? [] : [
      [input.counts.working, "working", "success", "working"],
      [input.counts.waiting, "waiting", "warning", "waiting"],
      [input.counts.failed, "failed", "error", "failed"],
    ];
  for (const [count, word, color, focus] of figures) {
    if (count > 0) {
      const label = count + " " + word;
      const drawn = chip(label, color);
      // The figure is the way to the rows it counts: a press opens the pane
      // already narrowed to them.
      parts.push(input.onOpen === undefined ? drawn
        : { type: "Button", props: { key: BAND_FOCUS + focus, label,
                                     onPress: () => input.onOpen?.(focus) },
            children: pressable([drawn]) });
      used += PART_GAP + label.length + 2;
    }
  }
  if (input.counts !== null && figures.every(([count]) => count === 0)) {
    parts.push(text({ dimColor: true }, "Nothing running"));
    used += PART_GAP + "Nothing running".length;
  }
  if (input.counts === null && input.note) {
    parts.push(text({ dimColor: true }, input.note));
    used += PART_GAP + input.note.length;
  }
  const dismiss = input.items.length > 0;
  // A band too narrow for the whole line gives up the product's name first,
  // then the speech switch's state word: the verb still says which way a press
  // goes, and nothing a person needs to read is cut.
  const dismissWidth = dismiss ? PART_GAP + "Dismiss".length + BUTTON_CHROME : 0;
  let fixed = used + dismissWidth;
  if (fixed > input.width) {
    const short = fleetLabel(input.open, input.surface, true);
    parts[0] = button(BAND_TOGGLE, short, input.onToggle, !input.open);
    used -= toggle.length - short.length;
    fixed = used + dismissWidth;
  }
  if (input.onSpeak !== undefined && fixed > input.width) {
    const speaking = input.speaking === true;
    const full = speakLabel(speaking, input.surface);
    const short = speakLabel(speaking, input.surface, true);
    parts[1] = button(BAND_SPEAK, short, input.onSpeak, speaking);
    used -= full.length - short.length;
  }
  if (gear !== null && gearAt >= 0 && used + dismissWidth > input.width) {
    const full = gear.label(false);
    const short = gear.label(true);
    parts[gearAt] = button(gear.key, short, gear.press);
    used -= full.length - short.length;
  }
  const room = input.width - used - PART_GAP - dismissWidth;
  const [first, ...others] = input.items;
  if (first !== undefined && room > 8) {
    const failing = others.filter((item) => item.level === "error").length;
    const waits = others.length - failing;
    const rest = [failing > 0 ? failing + " more failing" : "",
                  waits > 0 ? waits + " more waiting" : ""].filter(Boolean).join(", ");
    const lead = fit(first.text, Math.max(4, room - (rest ? rest.length + 3 : 0)));
    const words: Node[] = [
      text({ color: first.level, bold: true, wrap: "truncate-end" }, lead),
      ...(rest && lead.length + rest.length + 3 <= room
        ? [text({ dimColor: true }, " · " + rest)] : []),
    ];
    // What the band leads with is the way into it: a press opens the pane,
    // where the row it names is drawn with the rest of what it says.
    parts.push(box({ flexDirection: "row", gap: 0, flexShrink: 1 },
                   input.onOpen === undefined ? words
                     : [{ type: "Button",
                          props: { key: BAND_ITEM + first.key, label: lead,
                                   onPress: () => input.onOpen?.(undefined, first.key) },
                          children: pressable(words) }]));
  }
  const left = box({ flexDirection: "row", gap: 2, flexShrink: 1 }, parts);
  const row = dismiss
    ? box({ flexDirection: "row", justifyContent: "space-between", gap: 2 }, [
        left,
        button(BAND_DISMISS, "Dismiss", input.onDismiss),
      ])
    : box({ flexDirection: "row", gap: 0 }, [left]);
  // A rule across the band sets it apart from whatever the session drew above it,
  // so the buttons read as the fleet's own line. It is drawn dim: it separates
  // without competing with the figures and the item beside it.
  return box({ flexDirection: "column", gap: 0, marginBottom: 0 }, [
    text({ dimColor: true }, BAND_RULE.repeat(Math.max(0, input.width))),
    row,
  ]);
}

files.components/mount.ts:
/**
 * The one place the layout touches a host.
 *
 * The layout builds plain nodes; this module turns them into the host's own
 * elements. Keeping the boundary to one function means the layout tests need no
 * host at all, and the only cast in the tree lives here, next to the drift check
 * that fails when the host stops declaring a prop the layout writes. It is also
 * the one place a surface's vectors are chosen over its cells.
 */

import type { BoxProps, ButtonProps, InputProps, LinkProps, Node, Primitives, SvgProps,
              TextProps } from "./host.ts";

/** The engine's resolved elements, as the host hands them over at mount. */
export type HostElements = {
  Box: unknown;
  Text: unknown;
  Button: unknown;
  /** Only a surface that draws vectors hands one over. */
  Svg?: unknown;
  Link?: unknown;
  Input?: unknown;
};

/** The props of a node a drawing keeps: its address and its place, never its look. */
const PLACEMENT = ["key", "hover", "display", "marginTop", "marginBottom", "marginX", "marginLeft",
                   "marginRight"] as const;

/** The surfaces whose own table draws an Svg: every one but the terminal. */
const VECTOR_SURFACES = new Set(["desktop", "vscode", "mobile"]);

/**
 * The surfaces whose own table draws a text field: every one but the phone,
 * which the engine documents as drawing no field yet. Bound by name for the
 * reason the Svg is: a completed table hands the phone an Input that draws
 * nothing, and a reply field drawn as nothing is a reply nobody can send.
 */
const FIELD_SURFACES = new Set(["terminal", "desktop", "vscode"]);

/** Whether a surface draws a text field, so the pane offers one only where it does. */
export function drawsFields(surface: string): boolean {
  return FIELD_SURFACES.has(surface);
}

/**
 * The surfaces that draw a `plain` Button as the pane means it: as words among
 * the row, not as a filled control.
 *
 * The VS Code extension ignores `plain` and draws every Button as a filled
 * block at the width its parent gives it. In a row of actions that is a wall of
 * solid buttons, which is what a person sees instead of the pane's own words.
 */
const PLAIN_SURFACES = new Set(["terminal", "desktop", "mobile"]);

function plainButtons(surface: string): boolean {
  return PLAIN_SURFACES.has(surface);
}

/** How many cells the words of a button take: its label, or its children. */
function cellsOf(children: unknown[], label: string): number {
  const text = (child: unknown): number => {
    if (typeof child === "string") {
      return child.length;
    }
    if (child === null || typeof child !== "object") {
      return 0;
    }
    const node = child as { children?: unknown[]; props?: { label?: unknown } };
    const own = typeof node.props?.label === "string" ? node.props.label.length : 0;
    const inner = (node.children ?? []).reduce<number>((sum, one) => sum + text(one), 0);
    return Math.max(own, inner);
  };
  return Math.max(label.length, children.reduce<number>((sum, one) => sum + text(one), 0));
}

/**
 * A Button bound for a surface that fills every button, kept to the width its
 * own words take. The press stays a press; only the box around it is bounded.
 */
function pressedInline(button: unknown, box: unknown): Primitives["Button"] {
  const make = button as (props: unknown) => unknown;
  const wrap = box as (props: unknown) => unknown;
  return ((props: { label?: string; children?: unknown[] }) => {
    const label = typeof props.label === "string" ? props.label : "";
    const children = props.children ?? [];
    const drawn = make({ ...props, children });
    return wrap({ width: cellsOf(children, label) + 2, flexShrink: 0, children: [drawn] });
  }) as Primitives["Button"];
}

/**
 * The host's elements, declared as the narrow subset the layout uses.
 *
 * The host passes the elements it resolved for its own surface. Every surface
 * declares Box, Text and Button with the same props, so one binding serves them
 * all; `make components-drift` reads the engine's declaration and fails if any
 * stops carrying a prop named in host.ts.
 *
 * The Svg is bound by the surface's name, not by whether the table holds one:
 * the engine completes every table it hands out with every element name, and a
 * name the surface does not draw draws an empty fragment. Binding the terminal's
 * Svg would replace each bar and tile with nothing.
 */
export function bindPrimitives(elements: HostElements, surface: string): Primitives {
  return {
    Box: elements.Box as Primitives["Box"],
    Text: elements.Text as Primitives["Text"],
    Button: plainButtons(surface)
      ? elements.Button as Primitives["Button"]
      : pressedInline(elements.Button, elements.Box),
    ...(VECTOR_SURFACES.has(surface) && elements.Svg
      ? { Svg: elements.Svg as Primitives["Svg"] } : {}),
    // Every surface draws a link, so one is bound wherever the table holds it.
    ...(elements.Link ? { Link: elements.Link as Primitives["Link"] } : {}),
    ...(FIELD_SURFACES.has(surface) && elements.Input
      ? { Input: elements.Input as Primitives["Input"] } : {}),
  };
}

/**
 * Build the host's element for one node, and for everything under it.
 *
 * The host's element returns whatever that surface returns, so the mounted
 * result is opaque here on purpose: this function's job is handing the tree
 * over, not describing what the surface does with it.
 */
export function mount(tree: Node, primitives: Primitives): unknown {
  // A node with a drawing of itself is drawn as that drawing where the surface
  // draws vectors, in the slot its cells take: the box keeps the layout's width
  // and the drawing scales down into it. Everywhere else the cells are drawn.
  if (tree.vector && primitives.Svg) {
    const svg: SvgProps = { source: tree.vector.source, alt: tree.vector.alt };
    // What places the node among its siblings, and what addresses it, goes with
    // the drawing: a key or a hover lost here would be lost on the desktop alone.
    const placed: BoxProps = {};
    const props = tree.props as BoxProps;
    for (const name of PLACEMENT) {
      if (props[name] !== undefined) {
        (placed as Record<string, unknown>)[name] = props[name];
      }
    }
    return primitives.Box({ ...placed, width: tree.vector.cells, flexShrink: 0,
                            children: [primitives.Svg(svg) as Node] });
  }
  if (tree.type === "Input") {
    // A field is asked for only where one was bound, so a tree that holds one
    // here anyway is drawn without it rather than as an element the surface
    // completes into nothing.
    return primitives.Input ? primitives.Input(tree.props as InputProps)
      : primitives.Box({ children: [] });
  }
  const children: unknown[] = tree.children.map((child) =>
    typeof child === "string" ? child : mount(child, primitives));
  if (tree.type === "Link") {
    // Without a link the words are drawn as they read: the page is one press
    // fewer away, and nothing on the row is lost.
    return primitives.Link
      ? (primitives.Link as unknown as (props: unknown) => unknown)(
        { ...(tree.props as LinkProps), children })
      : (primitives.Text as unknown as (props: unknown) => unknown)({ children });
  }
  const element = tree.type === "Box" ? primitives.Box
                : tree.type === "Text" ? primitives.Text
                : primitives.Button;
  const build = element as unknown as (props: unknown) => unknown;
  return build({ ...tree.props, children });
}

/**
 * A recording host, for the layout tests.
 *
 * It returns the node it was given, so a test can assert the exact structure the
 * layout produces without a terminal or a desktop in the loop, and without
 * pretending that proves how either surface paints.
 */
export function recordingPrimitives(options: { vectors?: boolean; fields?: boolean;
                                            links?: boolean } = {}): Primitives {
  const record = (type: "Box" | "Text" | "Button" | "Svg" | "Link" | "Input") =>
    (props: BoxProps & TextProps & ButtonProps & { children?: (Node | string)[] }): Node => {
      const { children = [], ...rest } = props;
      return { type, props: rest, children };
    };
  // A recording of a surface that draws vectors, such as the desktop, holds an
  // Svg element; the default records the terminal's table, which has none.
  return {
    Box: record("Box") as Primitives["Box"],
    Text: record("Text") as Primitives["Text"],
    Button: record("Button") as Primitives["Button"],
    ...(options.vectors ? { Svg: record("Svg") as unknown as Primitives["Svg"] } : {}),
    // Links are on every surface, so a recording holds one unless a case asks
    // for a table without; a field only when a case records a surface with one.
    ...(options.links === false ? {} : { Link: record("Link") as unknown as Primitives["Link"] }),
    ...(options.fields ? { Input: record("Input") as unknown as Primitives["Input"] } : {}),
  };
}

files.components/alerts.ts:
/**
 * What in a reading is news: a job that finished or needs its person, a trial
 * that passed or failed, a skill flagged, a pull request whose checks fail.
 *
 * Each event carries a key that names it once across readings and across
 * sessions. A session alerts on what is new to it, and the machine-wide claim
 * on the key is what makes one session, not every open one, say it aloud.
 *
 * The first reading a session sees is not news: what was already true when it
 * opened is the band's to show, not an alert's to announce.
 */

import { isOwnJob } from "./band.ts";
import { mask } from "./mask.ts";
import type { Snapshot } from "./state.ts";

export type FleetEvent = {
  key: string;
  /** The line a toast and a notification show. */
  text: string;
  /** What is said aloud, for the events worth interrupting a person for. */
  spoken?: string;
};

/** What a value says once anything secret in it is masked. */
function said(value: string | null | undefined): string {
  return mask(value ?? "").text;
}

/** Everything in a reading worth one alert, each under a key that names it once. */
export function eventsOf(snapshot: Snapshot, sessionId: string): FleetEvent[] {
  const events: FleetEvent[] = [];
  for (const job of snapshot.roster.jobs) {
    if (isOwnJob(job, sessionId)) {
      continue;
    }
    // The key carries when the job entered its state, so a job that blocks a
    // second time is a second event, here and in the machine-wide claim.
    const since = job.since === null || job.since === undefined ? "" : ":" + Math.trunc(job.since);
    const name = said(job.name);
    if (job.state === "done") {
      events.push({ key: "job:" + job.id + ":done" + since, text: "Job finished: " + name });
    } else if (job.state === "blocked") {
      events.push({
        key: "job:" + job.id + ":blocked" + since,
        text: "Job needs you: " + name,
        spoken: job.needs ? "Hey, " + name + " has a question for you."
          : "Hey, " + name + " is waiting on you.",
      });
    }
  }
  for (const trial of snapshot.trials.recent) {
    const where = said(trial.repo) + " " + said(trial.branch);
    events.push({
      key: "trial:" + trial.key,
      text: trial.is_green
        ? "Trial passed on " + where + ": " + trial.passed + " passed"
        : "Trial failed on " + where + ": " + (trial.failed + trial.errors) + " failed, "
          + trial.passed + " passed",
    });
  }
  for (const skill of snapshot.skills.new ?? []) {
    const key = "skill:" + skill.target + ":" + skill.verdict + ":" + skill.hash;
    const name = said(skill.name);
    if (skill.verdict === "flagged") {
      events.push({ key, text: "Skill flagged: " + name + ", " + said(skill.issue) });
    } else if (skill.verdict === "failed") {
      events.push({ key, text: "Skill scan could not finish: " + name });
    } else {
      events.push({ key, text: "Skill to read: " + name + ", " + said(skill.issue) });
    }
  }
  for (const pull of snapshot.prs.prs) {
    if (pull.checks === "fail") {
      events.push({
        key: "pr:" + pull.repo + "#" + (pull.number ?? "") + ":" + pull.head,
        text: "PR " + (pull.number === null ? "" : pull.number + " ") + "checks failing: "
          + said(pull.title),
      });
    }
  }
  return events;
}

/** Whether any source this reading draws from could not be read. */
function degraded(snapshot: Snapshot): boolean {
  return [snapshot.roster, snapshot.trials, snapshot.prs, snapshot.skills]
    .some((source) => source.state === "failed" || source.state === "unavailable");
}

/**
 * The events to alert on now, and the keys to remember.
 *
 * Nothing is news on the first reading (`seen` is null). After that an event is
 * news once. The keys remembered are this reading's own, so a job that leaves
 * blocked and comes back to it alerts again; while a source could not be read
 * the earlier keys are kept as well, so a source that recovers does not replay
 * everything it holds as though it had just happened.
 */
export function newEvents(seen: readonly string[] | null, snapshot: Snapshot,
                          sessionId: string): { fresh: FleetEvent[]; seen: string[] } {
  const events = eventsOf(snapshot, sessionId);
  const keys = events.map((event) => event.key);
  if (seen === null) {
    return { fresh: [], seen: keys };
  }
  const known = new Set(seen);
  const fresh = events.filter((event) => !known.has(event.key));
  const remembered = degraded(snapshot) ? [...new Set([...seen, ...keys])] : keys;
  return { fresh, seen: remembered };
}

files.components/session.ts:
/**
 * This session's figures, from the engine rather than from a file.
 *
 * The session section once read a payload the status line was to write, and on
 * a machine whose status line writes none it was always empty. The engine hands
 * a plugin the same figures directly: what the session has cost, when it began,
 * its context window, its rate-limit windows, and its model. This turns them
 * into the document the section already draws, with every field the engine does
 * not report named as absent rather than drawn as nought.
 */

/** What the engine's usage call answers, as far as this module reads it. */
export type EngineUsage = {
  startedAt?: unknown;
  context?: { tokens?: unknown; window?: unknown; percent?: unknown } | null;
  rateLimits?: unknown;
  cost?: { usd?: unknown } | null;
};

/** The fields the section draws that the engine never reports. */
const NOT_FROM_ENGINE = ["apiDurationMs", "linesAdded", "linesRemoved", "inputTokens",
                         "outputTokens", "cacheReadTokens", "cacheCreationTokens",
                         "outputStyle", "modelName"];

/** Each rate-limit window the engine names, and the fields it fills. */
const WINDOWS: Record<string, { used: string; resets?: string }> = {
  five_hour: { used: "fiveHourUsedPercent", resets: "fiveHourResetsAt" },
  seven_day: { used: "sevenDayUsedPercent", resets: "weekResetsAt" },
  spend_limit: { used: "spendUsedPercent" },
};

/**
 * A money figure, to the cent, and never rounded to a nought.
 *
 * A cost below half a cent is not nothing, and `toFixed(2)` draws it as
 * "$0.00": a session that has spent something, drawn as one that has spent
 * none. Below a cent the figure is stated in the words that carry its size, as
 * the statusline already does for the same case.
 */
export function money(usd: number): string {
  if (usd !== 0 && Math.abs(usd) < 0.01) {
    return "~<$0.01";
  }
  return "$" + usd.toFixed(2);
}

/** One headline figure of the session section. */
export type SpendTile = { label: string; value: string; color?: "subtle" };

/**
 * The machine-wide spend tile, drawn beside this session's own cost.
 *
 * The figure is what every routed session wrote inside the configured window.
 * A reader that could not price it leaves it out, and the tile says so in the
 * quiet color: a machine nobody could measure is not a machine that spent
 * nothing, and "$0.00" would state the second claim from the first one's data.
 */
export function spendWindowTile(figures: { spendWindowUsd?: unknown }): SpendTile {
  const usd = figures.spendWindowUsd;
  if (typeof usd !== "number" || !Number.isFinite(usd) || usd < 0) {
    return { label: "24h routed", value: "not reported", color: "subtle" };
  }
  return { label: "24h routed", value: money(usd) };
}

/** The figures the reader priced across the machine, kept over the engine's document. */
const SPEND_FIELDS = ["spendWindowUsd", "spendWindowFiles", "spendWindowSkipped"] as const;

function finite(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : null;
}

/** A time the engine wrote as text, in seconds since the epoch, or null. */
function seconds(value: unknown): number | null {
  if (typeof value !== "string") {
    return null;
  }
  const at = Date.parse(value);
  return Number.isFinite(at) ? at / 1000 : null;
}

/**
 * The windows the reader reports for this session's own provider, filling the
 * rows a subscription session's five-hour and weekly windows fill.
 *
 * The reader is the only layer that can read a rollout or the status line's
 * own file, and it names each window by the length of time it spans: five
 * hours and a week are the two a person watches, and they are drawn under
 * those names. A window of another length is left out rather than drawn under
 * a name it does not have, and a limit that is not a ready reading of a
 * provider that reports windows contributes nothing.
 */
const WINDOW_PROVIDERS = new Set(["codex", "claude"]);

function providerWindows(limits: unknown): Record<string, number> {
  if (typeof limits !== "object" || limits === null) {
    return {};
  }
  const read = limits as { state?: unknown; provider?: unknown; windows?: unknown };
  if (read.state !== "ready" || typeof read.provider !== "string"
      || !WINDOW_PROVIDERS.has(read.provider) || !Array.isArray(read.windows)) {
    return {};
  }
  const rows: Record<string, number> = {};
  for (const entry of read.windows) {
    if (typeof entry !== "object" || entry === null) {
      continue;
    }
    const window = entry as { windowMinutes?: unknown; usedPercent?: unknown;
                              resetsAt?: unknown };
    const used = finite(window.usedPercent);
    const resets = finite(window.resetsAt);
    if (window.windowMinutes === 300) {
      if (used !== null && used <= 100) {
        rows.fiveHourUsedPercent = used;
      }
      if (resets !== null) {
        rows.fiveHourResetsAt = resets;
      }
    } else if (window.windowMinutes === 10080) {
      if (used !== null && used <= 100) {
        rows.sevenDayUsedPercent = used;
      }
      if (resets !== null) {
        rows.weekResetsAt = resets;
      }
    }
  }
  return rows;
}

/**
 * The session section's document from what the engine reported.
 *
 * `now` is in milliseconds, the engine clock's own unit, and so is the usage's
 * `startedAt`. Null when the usage is not a usage at all, so a caller keeps
 * whatever document it had rather than drawing an empty session.
 */
export function sessionDocument(usage: unknown, model: unknown, version: unknown,
                                sessionId: string, now: number): Record<string, unknown> | null {
  if (typeof usage !== "object" || usage === null) {
    return null;
  }
  const read = usage as EngineUsage;
  const document: Record<string, unknown> = { state: "ready", errors: [], parameters: {} };
  const absent: string[] = [...NOT_FROM_ENGINE];
  const put = (name: string, value: number | string | null) => {
    if (value === null) {
      absent.push(name);
    } else {
      document[name] = value;
    }
  };
  put("costUsd", finite(read.cost?.usd));
  const started = finite(read.startedAt);
  put("durationMs", started !== null && now >= started ? now - started : null);
  put("windowSize", finite(read.context?.window));
  const percent = finite(read.context?.percent);
  put("remainingPercent", percent !== null && percent <= 100 ? 100 - percent : null);
  const limits = Array.isArray(read.rateLimits) ? read.rateLimits : [];
  for (const [kind, fields] of Object.entries(WINDOWS)) {
    const found = limits.find((limit) => typeof limit === "object" && limit !== null
      && (limit as { kind?: unknown }).kind === kind) as
      { percentUsed?: unknown; resetsAt?: unknown } | undefined;
    put(fields.used, finite(found?.percentUsed));
    if (fields.resets) {
      put(fields.resets, seconds(found?.resetsAt));
    }
  }
  put("model", typeof model === "string" && model ? model : null);
  const named = typeof version === "object" && version !== null
    ? (version as { version?: unknown }).version : null;
  put("version", typeof named === "string" && named ? named : null);
  put("sessionId", sessionId || null);
  document.absent = absent;
  return document;
}

/**
 * The documents a paint draws from: the reading's, with this session's figures
 * taken from the engine when the engine has answered.
 *
 * The engine's figures are this session's own and current, so they stand over
 * a payload file, which may be another session's and is as old as its last
 * write. A reading that is not an object is handed back untouched.
 */
export function withSession(documents: unknown, engine: Record<string, unknown> | null): unknown {
  if (typeof documents !== "object" || documents === null) {
    return documents;
  }
  const reading = documents as Record<string, unknown>;
  const fromReader = typeof reading.session === "object" && reading.session !== null
    ? reading.session as Record<string, unknown> : {};
  // A Codex session's windows are read from its rollout, and a Claude
  // session's from the file the status line writes, not from the engine, which
  // reports no rate limits on either. They fill the rows the subscription
  // session already draws, and stand over a reading's own fields because they
  // are this session's current figures.
  const windows = providerWindows(fromReader.limits);
  const provider = typeof fromReader.providerCostUsd === "number"
    && Number.isFinite(fromReader.providerCostUsd) ? fromReader.providerCostUsd : null;
  // The window spend is the machine's, read from files the engine never sees,
  // so it is carried over the engine's document rather than dropped with the
  // payload figures it replaces.
  const spend: Record<string, unknown> = {};
  for (const name of SPEND_FIELDS) {
    const value = fromReader[name];
    if (typeof value === "number" && Number.isFinite(value)) {
      spend[name] = value;
    }
  }
  const merged = { ...engine, ...spend };
  if (engine === null) {
    if (Object.keys(windows).length === 0) {
      return documents;
    }
    return { ...reading, session: { ...fromReader, ...windows } };
  }
  // A routed session's money is the figure the status line priced from that
  // session's own transcript. The engine's cost is an Anthropic-table number,
  // and on a session routed to another provider it is not that provider's
  // spend; every other engine field still stands over the reading.
  const priced = provider === null ? merged
    : { ...merged, costUsd: provider, providerCostUsd: provider, costSource: "provider" };
  return { ...reading, session: { ...priced, ...windows } };
}

files.components/motion.ts:
/**
 * What moves on the pane, decided by comparing this paint with the last one.
 *
 * A row that was not drawn last time slides in from the right on a tint; a row
 * that was drawn and is gone slides out where it stood; a section that goes
 * slides out whole; and warnings that arrive or change blink for a while. Each
 * movement is a short span of time measured on the engine's clock, so the
 * caller asks for frames only while `moving` says something is still in
 * flight, and the pane holds still the rest of the time.
 *
 * The first paint moves nothing: rows that were already there when the pane
 * opened did not arrive, and a pane that slid every row in on opening would be
 * telling a person about news that is not news.
 */

import type { Group, Pane, Row } from "./layout.ts";

/** How long a row takes to slide in or out, in milliseconds. */
export const SLIDE_MS = 360;
/** How far a row starts from, or travels to, in cells. */
export const SLIDE_CELLS = 6;
/** How long warnings blink after they arrive or change. */
export const BLINK_MS = 3000;
/** How long each half of a blink lasts. */
export const BLINK_PERIOD_MS = 400;

const WARNINGS = "warnings";

type Placed = { group: string; row: Row; index: number };
type Leaving = Placed & { at: number };
type GroupLeaving = { group: Group; index: number; at: number };

/** What the last paint drew, and what is in flight since. */
export type Motion = {
  primed: boolean;
  rows: Map<string, Placed>;
  groups: Map<string, { group: Group; index: number }>;
  arrived: Map<string, number>;
  leaving: Map<string, Leaving>;
  groupsLeaving: Map<string, GroupLeaving>;
  warned: string;
  blinkFrom: number | null;
};

export function motionMemory(): Motion {
  return { primed: false, rows: new Map(), groups: new Map(), arrived: new Map(),
           leaving: new Map(), groupsLeaving: new Map(), warned: "", blinkFrom: null };
}

/** A section's id: its fold control's address, or its title when it has none. */
function groupId(group: Group): string {
  return group.toggle?.key ?? group.title;
}

function rowId(group: string, row: Row): string {
  return group + "|" + (row.key ?? row.title);
}

function isWarnings(group: Group): boolean {
  return (group.toggle?.key ?? "").endsWith("." + WARNINGS);
}

/** Eased so a row decelerates into place rather than stopping dead. */
function eased(progress: number): number {
  const clamped = Math.max(0, Math.min(1, progress));
  return 1 - (1 - clamped) * (1 - clamped);
}

/**
 * The pane to draw now, with what is moving marked on it, and whether anything
 * still is. `memory` is the caller's, kept across paints.
 */
export function animate(pane: Pane, memory: Motion, now: number): { pane: Pane; moving: boolean } {
  const rows = new Map<string, Placed>();
  const groups = new Map<string, { group: Group; index: number }>();
  pane.groups.forEach((group, index) => {
    const id = groupId(group);
    groups.set(id, { group, index });
    if (group.collapsed) {
      return;
    }
    group.rows.forEach((row, at) => rows.set(rowId(id, row), { group: id, row, index: at }));
  });
  const warnings = pane.groups.find(isWarnings);
  const warned = warnings && !warnings.collapsed
    ? warnings.rows.map((row) => row.title).join("\n") : "";

  if (!memory.primed) {
    memory.primed = true;
    memory.rows = rows;
    memory.groups = groups;
    memory.warned = warned;
    return { pane, moving: false };
  }

  for (const id of rows.keys()) {
    if (!memory.rows.has(id) && !memory.arrived.has(id)) {
      memory.arrived.set(id, now);
    }
    memory.leaving.delete(id);
  }
  for (const [id, placed] of memory.rows) {
    if (rows.has(id)) {
      continue;
    }
    // A row whose section is still drawn open slides out of it; one whose
    // section went slides out with the section, below.
    const holder = groups.get(placed.group);
    if (holder && !holder.group.collapsed && !memory.leaving.has(id)) {
      memory.leaving.set(id, { ...placed, at: now });
    }
  }
  for (const [id, held] of memory.groups) {
    if (!groups.has(id) && !memory.groupsLeaving.has(id) && !held.group.collapsed
        && held.group.rows.length) {
      memory.groupsLeaving.set(id, { ...held, at: now });
    }
  }
  for (const id of groups.keys()) {
    memory.groupsLeaving.delete(id);
  }
  if (warned && warned !== memory.warned) {
    memory.blinkFrom = now;
  }
  if (!warned) {
    memory.blinkFrom = null;
  }
  memory.warned = warned;
  memory.rows = rows;
  memory.groups = groups;

  for (const [id, at] of memory.arrived) {
    if (now - at >= SLIDE_MS) {
      memory.arrived.delete(id);
    }
  }
  for (const [id, leaving] of memory.leaving) {
    if (now - leaving.at >= SLIDE_MS) {
      memory.leaving.delete(id);
    }
  }
  for (const [id, leaving] of memory.groupsLeaving) {
    if (now - leaving.at >= SLIDE_MS) {
      memory.groupsLeaving.delete(id);
    }
  }
  const blinking = memory.blinkFrom !== null && now - memory.blinkFrom < BLINK_MS;

  const drawn = pane.groups.map((group) => {
    const id = groupId(group);
    if (group.collapsed || group.state === "paused") {
      return group;
    }
    const marked: Row[] = group.rows.map((row) => {
      const at = memory.arrived.get(rowId(id, row));
      if (at === undefined) {
        return row;
      }
      const offset = Math.round((1 - eased((now - at) / SLIDE_MS)) * SLIDE_CELLS);
      return { ...row, motion: { offset, arriving: true } };
    });
    // Leaving rows go back where they stood, in the order they stood in.
    const going = [...memory.leaving.values()].filter((leaving) => leaving.group === id)
      .sort((a, b) => a.index - b.index);
    for (const leaving of going) {
      const offset = Math.round(eased((now - leaving.at) / SLIDE_MS) * SLIDE_CELLS);
      marked.splice(Math.min(leaving.index, marked.length), 0,
                    { ...leaving.row, motion: { offset, leaving: true } });
    }
    const blink = isWarnings(group) && blinking
      ? Math.floor((now - (memory.blinkFrom as number)) / BLINK_PERIOD_MS) % 2 === 0
      : undefined;
    return { ...group, rows: marked, ...(blink !== undefined ? { blink } : {}) };
  });
  const goneGroups = [...memory.groupsLeaving.values()].sort((a, b) => a.index - b.index);
  for (const gone of goneGroups) {
    const offset = Math.round(eased((now - gone.at) / SLIDE_MS) * SLIDE_CELLS);
    drawn.splice(Math.min(gone.index, drawn.length), 0, {
      ...gone.group,
      rows: gone.group.rows.map((row) => ({ ...row, motion: { offset, leaving: true } })),
    });
  }
  const moving = memory.arrived.size > 0 || memory.leaving.size > 0
    || memory.groupsLeaving.size > 0 || blinking;
  return { pane: { ...pane, groups: drawn }, moving };
}

files.components/layout.ts:
/**
 * The shared layout: descriptors in, Box and Text nodes out.
 *
 * This module is the whole reason the layout is testable without a host. It
 * takes a description of what should be on screen and returns a tree built only
 * from the two primitives in host.ts, so a test can read the structure and
 * assert it, on either surface, at any width.
 *
 * Three rules are structural rather than cosmetic, and the tests exist to keep
 * them that way:
 *
 * - a bar is drawn only when a real denominator exists, and it is never drawn
 *   for a value that contradicts itself (done above total),
 * - a long title is truncated, and never the state, the failure, the source
 *   error, or the denominator,
 * - a group that failed says it failed even while it is collapsed.
 */

import type { BoxProps, ButtonProps, Color, InputProps, Node, TextProps, Tree } from "./host.ts";
import { FOLDED, OPENED, checkDots, historyStrip, rateBar, sparkline, stateColor, statStrip,
         statusDot, tag, tagTexts, timelineStrip, titleChip } from "./cards.ts";
import { tileVector } from "./vector.ts";

/**
 * Something a person can press, and the address a press comes back on.
 *
 * The address is the element's `key`: a `ui.press` hook receives it as
 * `e.element`, which is how the entry knows which section was folded.
 */
export type Control = {
  key: string;
  label: string;
  /** What a press does, run by the host in the plugin's own environment. */
  onPress: () => void;
  /** One digit or one lowercase letter that presses it while the pane has focus. */
  hotkey?: string;
  dim?: boolean;
};

/**
 * One section in the pane's picker: the name it is known by, whether a person
 * put it away, and the press that puts it away or brings it back.
 *
 * A section a person put away is not drawn among the cards, but its name stays
 * here, dim, because the picker is the only way back: dropping it would make
 * the press that hid it one a person cannot undo.
 */
export type PickerItem = {
  /** The section's identifier in the resolved order, such as `sessions`. */
  name: string;
  /** What the section is called, which is what the picker draws. */
  title: string;
  hidden: boolean;
  press: Control;
};

export type Slot = {
  text: string;
  color?: Color;
  dim?: boolean;
  bold?: boolean;
  /**
   * The column this slot is drawn in, in cells, and which end it sits at.
   *
   * A figure drawn at the width it happens to need puts whatever follows it one
   * cell apart from row to row, so a column of percentages walks out of line
   * against the column beside it. A width is a claim that this slot holds a
   * column: the text is padded inside it, and the next slot starts where the
   * column ends.
   */
  width?: number;
  align?: "left" | "right";
};

export type Bar = {
  done: number;
  total: number;
  failed?: number;
  /** Whether the run behind these counts is still going. */
  stopped?: boolean;
  /**
   * What is written under the bar, instead of the counts this file computes.
   *
   * A row that states its own counts beside the bar would say them twice if the
   * computed label were drawn as well, so the label is what a caller overrides.
   * Absent is the computed label and `null` is nothing: those are two different
   * answers, and a row whose only job is the bar has to be able to give the
   * second one.
   */
  label?: Slot | null;
  /**
   * How many cells the bar is drawn with, when the configuration fixes a length.
   *
   * Absent is the width the row was given. A configured length is capped by that
   * width rather than overflowing it, because a bar longer than the card it sits
   * in is a bar whose end nobody sees.
   */
  cells?: number;
};

/**
 * One bucket of a period, for the strip drawn across the top of a section.
 *
 * `outcomes` is how many things landed in the bucket and `failed` how many of
 * them did not pass. A bucket with nothing in it is drawn as track rather than
 * as a pass, because an hour nobody tried anything is not an hour that went
 * well.
 */
export type HistoryCell = {
  outcomes: number;
  failed: number;
};

/**
 * A stretch of the recent past, one cell per bucket, oldest first.
 *
 * It is drawn as its own line under the heading, above the rows, which is where
 * a reader looks for "how has the day gone" before reading any single row. It is
 * drawn only when the period holds something: a strip of empty cells is a claim
 * about twelve hours nobody measured.
 */
export type History = {
  /** What the strip covers, such as "Last 12 hours". */
  label: string;
  cells: HistoryCell[];
  /** What the buckets add up to, which is what the caption states. */
  outcomes: number;
  failed: number;
};

/**
 * A line an item draws at rest under its first two: a subagent task it runs, the
 * reply it suggests, or what happens to it next. A line that carries a press is
 * one control, every word of it, which is how a suggestion is copied on a
 * surface that draws no field to send it from.
 */
export type RowLine = {
  slots: Slot[];
  press?: Control;
  /** Set in italic: the item's own words rather than the pane's. */
  italic?: boolean;
};

/** A text field under an item, such as the reply a waiting job is sent. */
export type Field = Omit<InputProps, "key"> & { key: string };

export type Row = {
  /**
   * What this row is, stable across readings: the address its hover scope and
   * its motion are keyed on. Absent, the row is addressed by its place.
   */
  key?: string;
  title: string;
  /**
   * The project this row belongs to, when the section is drawn as a tree.
   *
   * The renderer prints the root as a heading the first time a project's rows
   * are reached and hangs the rows under it one rail deeper, so the section
   * reads as one tree per project rather than a flat list of items nobody can
   * attribute. `last` is true for the section's last project, whose rail closes
   * into the section's line.
   */
  project?: { root: string; count: number; last: boolean };
  /**
   * What a press on the title does, when it does anything: the title is then a
   * control, every cell of it, so a person presses the thing they read.
   */
  press?: Control;
  /** Where the title links to, when it is a page: drawn as a link, opened by the surface. */
  link?: string;
  /** Lines drawn at rest under the row's first two, each its own. */
  lines?: RowLine[];
  /** A field under the row, on a surface that draws one. */
  field?: Field;
  /** A row of the past, such as a finished job: every part of it drawn quiet. */
  dim?: boolean;
  /**
   * How far the row stands from its place while it slides in or out, in cells,
   * and which way it is going. Absent for a row at rest, which is nearly all.
   */
  motion?: { offset: number; arriving?: boolean; leaving?: boolean };
  /**
   * What this row is doing, for the dot beside it.
   *
   * Absent when the row is not a state at all, which is most of them: a dot for
   * a thing that is not in one of those states would be a verdict this pane has
   * no basis for.
   */
  state?: string;
  meta: Slot[];
  slot: Slot[];
  /** A line of its own, such as what a waiting job asks. */
  detail?: string;
  bar?: Bar;
  /**
   * What the row measured, stated at the right of the bar's line with the bar's
   * own label at the left and the bar across the card under both: the shape the
   * host's Agents panel draws a session in. Absent, the bar keeps its counts
   * beside it or under it.
   */
  figures?: Slot[];
  /** What could not be read or proved about this row. */
  note?: Slot;
  /**
   * What the row holds in full, drawn under it once the row is opened.
   *
   * The two lines at rest are what a person scans; these are what they read
   * after pressing the row's figures, where the facts live that would make
   * every row three lines tall if they were always drawn.
   */
  details?: Slot[];
  /** The press that opens the row, drawn on its figures. */
  detailsPress?: Control;
  /** Whether the details are drawn now. */
  expanded?: boolean;
  /**
   * Checks drawn as dots at the right of the first line, one per check in its
   * state, and how many the reader left out, which are counted beside them.
   */
  checks?: { states: string[]; more: number };
  /**
   * The row's working, idle and waiting stretches, drawn as a line across the
   * card from `from` to `to` (epoch seconds). `tail` is the state from the last
   * stretch to `to`, when the row knows it; time no stretch covers is unknown.
   */
  timeline?: Timeline;
};

export type Timeline = {
  from: number;
  to: number;
  segments: { start: number; end: number; state: string }[];
  tail?: string;
};

/** A series drawn as one line of block glyphs, with the words that say what it adds up to. */
/**
 * A series and its label. `keep` is how many of the label's first segments are
 * drawn whole however narrow the card: the figure, and the mark that says it is
 * a floor, are what the line means, and the series gives up its room first.
 */
export type Spark = { values: number[]; label: Slot[]; keep?: number };

/**
 * What happened while the person was away, drawn under the pane's controls.
 *
 * `through` is the newest event it drew, which the entry keeps as the person's
 * last look when the pane closes; null when it drew no event, as when the
 * events could not be read.
 */
export type Digest = {
  title: string;
  tone: Color;
  heading: Slot[];
  lines: Slot[][];
  through: number | null;
};

export type GroupState = "ready" | "empty" | "disabled" | "failed" | "stale" | "unavailable" | "paused";

export type Group = {
  /**
   * Which half of a blink the section is in while its warnings are new: its rule
   * swaps between the warning and the error color. Absent while it holds still.
   */
  blink?: boolean;
  /** The name used in a sentence about the group, such as "Background jobs". */
  name: string;
  title: string;
  summary: Slot[];
  rows: Row[];
  state: GroupState;
  collapsed?: boolean;
  /**
   * The control that folds this section, when the pane offers one.
   *
   * Its label carries the fold mark, so what a person reads is the state the
   * section is in rather than a word that has to be interpreted.
   */
  toggle?: Control;
  /**
   * The lines the section keeps under its heading while it is open, made up
   * with blank lines when it holds less: a section whose items come and go in
   * seconds otherwise moved every section below it each time.
   */
  reserve?: number;
  /**
   * Names for the figures a section draws in its rows' right-hand columns.
   *
   * A figure whose meaning a person has to infer from its shape, such as a
   * percentage and a byte count in two aligned columns, is named once above the
   * rows. A section whose right slot is a state word or a measured count names
   * nothing: there the slot already says what it is.
   */
  columns?: Slot[];
  /** Rows a stale group still carries, and how old the last good read is. */
  observed?: number;
  staleSeconds?: number;
  /** What failed, when the group failed. */
  failure?: string;
  /** The sentence a section uses when it is switched off, and when it is empty. */
  disabledText?: string;
  emptyText?: string;
  /**
   * What this section's counts mean, as the configuration words it.
   *
   * Drawn under the heading while the section is open. It is the one line that
   * says a count is of trials, or of worktrees, or of sources that could not be
   * read, which is what a row of numbers at the right of a heading cannot say
   * for itself.
   */
  legend?: string | null;
  /**
   * The recent past drawn as a strip, when the section has one to draw.
   *
   * It belongs to the section rather than to a row: no single row is the day.
   */
  history?: History | null;
  /**
   * The section's headline figures, drawn as small cards above its rows: a
   * label and a value each, as the host's Agents panel heads a run with its
   * cost, tokens and time. A figure nobody reported is a tile that says so.
   */
  tiles?: Tile[];
  /**
   * Lines the section draws under its rows while it is open: what the rows do
   * when pressed, and what it knows that is no row of its own, such as how many
   * interactive sessions each provider runs.
   */
  notes?: Slot[][];
  /**
   * Rows the section held back to keep its height, drawn under it while the
   * pointer is on it.
   *
   * A heading that says "3 more" without them is a count a person can only take
   * on trust; the rows are already read and masked, so showing them costs no
   * more than the count did.
   */
  held?: Row[];
  /** A series the section draws under its heading while open, such as spend over the day. */
  spark?: Spark | null;
  /**
   * Whether the section holds something that needs the person: a failed check,
   * a job waiting on input, a failed trial or run. Such a section is drawn above
   * the calm ones.
   */
  attention?: boolean;
};

/** One headline figure of a section. */
export type Tile = { label: string; value: string; color?: Color };

/**
 * A headline figure that is also the way into what it counts.
 *
 * A figure a person reads and cannot act on leaves them to find the rows
 * themselves; pressing the card narrows the pane to the items in that state,
 * which is the thing the number made them want.
 */
export type PaneCard = {
  label: string;
  value: string;
  color?: Color;
  press?: Control;
};

export type Pane = {
  title: string;
  /**
   * The headline figures, drawn as a row of cards under the title.
   *
   * Each is a count the pane is already going to state, given the prominence the
   * figures at the top of a panel get. A figure the machine did not give is not
   * a card: a card is the loudest thing on the pane, and a zero there is the
   * strongest claim it could make.
   */
  cards?: PaneCard[];
  /** The counts as a line of text, for a caller that draws no cards. */
  counts: Slot[];
  updated: Slot;
  warning?: Slot;
  /** The controls that act on every section at once, drawn under the counts. */
  controls?: Control[];
  /**
   * The sections the configuration made visible, each with the press that puts
   * it away or brings it back.
   *
   * Drawn under the controls, one line or several as the width holds them. A
   * section a person put away keeps its name here, drawn dim, and the same
   * press restores it.
   */
  picker?: PickerItem[];
  /** What closes the pane, said beside the controls in the words a person types. */
  hint?: string;
  /**
   * The filter a press on a headline figure set, and the press that clears it.
   *
   * Drawn under the controls, so a narrowed pane never reads as a small fleet:
   * the figures at the top still state the whole machine, and this line says
   * why only some of its rows are under them.
   */
  focus?: { text: string; clear: Control };
  /** What happened since the person last looked, when there is anything to say. */
  digest?: Digest | null;
  /**
   * The line under the last card: what this is, its version and its license.
   *
   * It is the one place a person finds the version to quote when something is
   * wrong, so it is drawn dim and whole wherever the width holds it.
   */
  footer?: Slot;
  groups: Group[];
  /** Columns the surface offers. */
  width: number;
  /** Below this width the right slot moves to its own line. */
  narrowAt: number;
};

export const BAR_FILLED = "#";
export const BAR_EMPTY = "-";
export const TRUNCATION = "...";
/** What sits between two readings on one line: the host's own middle dot. */
export const SEPARATOR = "\u00b7";

export function text(props: TextProps, value: string): Node {
  return { type: "Text", props, children: [value] };
}

export function box(props: BoxProps, children: (Node | string)[]): Node {
  return { type: "Box", props, children };
}

/**
 * A row of segments, each with its own color, on one line.
 *
 * Segments are separated by one space unless a segment asks to be joined to the
 * one before it, which is how a caller writes a punctuation-first segment. Two
 * readings placed next to each other without a gap read as one wrong reading.
 */
export function line(slots: Slot[], props: TextProps = {}): Node {
  // A segment stays on its line. The layout already cuts each one to the room
  // it has; the host, given a narrower cell than the layout measured on, would
  // otherwise wrap the remainder onto a second line and take the row's height
  // with it. A cut word is a cut word; a wrapped one is a broken row.
  return box({ flexDirection: "row", gap: 0 },
             slots.map((slot, index) => text(
               { wrap: "truncate-end", ...props, ...slotProps(slot) },
               index === 0 || slot.text.startsWith(" ") ? slot.text : " " + slot.text)));
}

export function slotProps(slot: Slot): TextProps {
  const props: TextProps = {};
  if (slot.color) {
    props.color = slot.color;
  }
  if (slot.dim) {
    props.dimColor = true;
  }
  if (slot.bold) {
    props.bold = true;
  }
  return props;
}

/** Text cut to a width, with the cut marked so a reader knows it happened. */
export function fit(value: string, width: number): string {
  if (width <= 0) {
    return "";
  }
  if (value.length <= width) {
    return value;
  }
  if (width <= TRUNCATION.length) {
    return value.slice(0, width);
  }
  return value.slice(0, width - TRUNCATION.length) + TRUNCATION;
}

/**
 * Text cut to a width, without splitting the word the cut lands in.
 *
 * A segment can hold more than one fact, and the strip's last one holds a
 * duration and the word after it. Cut on the character it drew "10h 29m lon...",
 * which reads as a figure rather than as a line that was cut. A cut that lands
 * inside a word backs up to the last boundary; a cut that lands on one keeps the
 * word whole, and a single word with no boundary to back up to is cut where it
 * lands rather than dropped, because a line saying less is worse than a line
 * saying half.
 */
function cutToWord(value: string, width: number): string {
  const fitted = fit(value, width);
  if (fitted.length >= value.length || !fitted.endsWith(TRUNCATION)) {
    return fitted;
  }
  const body = fitted.slice(0, fitted.length - TRUNCATION.length);
  // What the cut landed on decides it: whitespace or the end of the value means
  // the text stopped at a boundary, and anything else means half a word.
  const next = value.charAt(body.length);
  if (next === "" || /\s/.test(next)) {
    return fitted;
  }
  const boundary = body.search(/\s\S*$/);
  return boundary > 0 ? body.slice(0, boundary) + TRUNCATION : fitted;
}

/**
 * A bar's cells for a denominator that can be trusted.
 *
 * A count above its total is not drawn: the caller reports the contradiction
 * instead, because a full-looking bar over impossible counts is exactly the
 * claim this design refuses to make.
 */
export function barCells(cells: number, done: number, total: number): string {
  if (cells <= 0 || total <= 0 || done < 0 || done > total) {
    return "";
  }
  const filled = Math.max(0, Math.min(cells, Math.round((done / total) * cells)));
  return BAR_FILLED.repeat(filled) + BAR_EMPTY.repeat(cells - filled);
}

/** What a row with no trustworthy denominator says instead of a bar. */
export function countLabel(bar: Bar | undefined): Slot {
  if (!bar || !Number.isFinite(bar.total) || !Number.isFinite(bar.done) || bar.total <= 0) {
    return { text: "No counts yet", color: "warning" };
  }
  if (bar.done > bar.total) {
    return { text: `${bar.done} of ${bar.total}`, color: "error" };
  }
  return { text: `${bar.done} / ${bar.total}`, color: "text" };
}

/** The wording a group with nothing to show uses, by why it has nothing. */
export function groupMessage(group: Group): Slot[] {
  const age = ageText(group.staleSeconds ?? 0);
  switch (group.state) {
    case "paused":
      return [{ text: `${group.name} is paused.`, dim: true }];
    case "empty":
      return [{ text: group.emptyText ?? `No ${group.name.toLowerCase()} here.`, dim: true }];
    case "disabled":
      return [{ text: group.disabledText ?? `${group.name} is disabled in configuration.`,
                dim: true }];
    case "unavailable":
      return [{ text: `Could not read ${group.failure ?? group.name}. Count unknown.`,
                color: "warning" }];
    case "failed":
      return [{ text: `Could not read ${group.failure ?? group.name}. Count unknown.`,
                color: "error" }];
    case "stale":
      return [{ text: `${group.observed ?? 0} observed, as of ${age}. Refresh failed.`,
                color: "warning" }];
    default:
      return [];
  }
}

/**
 * A length of time, without saying which way it points.
 *
 * `ageText` answers "how long ago"; a duration is what a sentence like "lease
 * ends in 10m" or "waiting 5m" needs, and joining the two produces the nonsense
 * this pair exists to prevent.
 */
export function durationText(seconds: number): string {
  return ageText(seconds).replace(/ ago$/, "");
}

export function ageText(seconds: number): string {
  if (seconds < 60) {
    return `${Math.max(0, Math.round(seconds))}s ago`;
  }
  if (seconds < 3600) {
    return `${Math.round(seconds / 60)}m ago`;
  }
  if (seconds < 86400) {
    return `${Math.round(seconds / 3600)}h ago`;
  }
  return `${Math.round(seconds / 86400)}d ago`;
}

/**
 * A section's project root, drawn once above the rows that belong to it.
 *
 * The root is set in the theme's accent so a reader tells one project from the
 * next without counting indents, and its count is the items under that root
 * rather than the section's total, which its heading already states.
 */
function renderProject(project: { root: string; count: number }, width: number,
                       rail?: Rail): Node {
  // A picture surface draws no rail glyph: the root is the card's own line,
  // and the rows under it are set apart by the card rather than by a branch.
  const drawn = rail === undefined ? [] : [
    text({ color: rail.color, ...(rail.dim ? { dimColor: true } : {}) }, rail.first),
  ];
  const label = fit(project.root, Math.max(8, width - (rail?.first.length ?? 0) - 12));
  const count = project.count + (project.count === 1 ? " item" : " items");
  return box({ flexDirection: "row", gap: 1 }, [
    ...drawn,
    text({ color: "claude", bold: true }, label),
    text({ dimColor: true }, count),
  ]);
}

/**
 * The mark a section's items hang off, beside each line an item draws: a branch
 * on its first line and the rail running on beside the rest, or the closing
 * branch and nothing for the last item.
 */
export type Rail = {
  first: string;
  rest: string;
  color: Color;
  dim?: boolean;
  /**
   * What stands before this row's branch on the section's rail: the parent's
   * rail at full width while the row is one of several under it, and blank when
   * it is the last, so the branch closes into the section's line.
   */
  prefix?: string;
};

/** The rail's own glyphs. */
export const RAIL_BRANCH = "├─";
export const RAIL_LAST = "└─";
export const RAIL_ON = "│ ";
export const RAIL_END = "  ";

/** The states whose item is a question for a person rather than a measurement. */
const ASKING = new Set(["waiting", "blocked"]);

/**
 * One item, in two lines at rest.
 *
 * The first says what it is and how it stands: the state dot, the title, who or
 * what runs it, and its headline figures at the right. The second says how far
 * along it is, as a bar with its label, or, for an item that waits on a person,
 * what it asks. Whatever else the item has to say for itself waits for the
 * pointer: two lines an item is what lets a pane a few dozen rows high show a
 * whole section instead of two items of it.
 *
 * Every line is cut to the width it was given, because a text too long for its
 * line wraps into columns of its own and takes the lines below with it.
 */
export function renderRow(row: Row, width: number, narrowAt: number,
                          key?: string, rail?: Rail): Node {
  const offset = Math.max(0, Math.round(row.motion?.offset ?? 0));
  const railWidth = rail ? (rail.prefix?.length ?? 0) + RAIL_BRANCH.length + 1 : 0;
  // The row is laid out at the width it has at rest, and the slide's offset is
  // taken from the dim middle text alone: cut to the room left after the
  // offset, the title's ellipsis moved a cell on every frame of a slide.
  const resting = Math.max(8, width - railWidth);
  const inner = Math.max(8, resting - offset);
  const stacked = resting < narrowAt;
  // The figures stand at the right when the row has them; a row without any
  // states its slot there instead.
  const rightSlots = row.figures && row.figures.length ? row.figures
    : row.slot.map((part, index) => index === 0 ? { ...part, bold: true } : part);
  const fill = titleChip(row.state ?? "");
  // The figures take their room before the title does: a state or a verdict is
  // what the row is read for, and a title cut to keep it is still a title. What
  // the title is given is what is left, rather than a flat share of the line: a
  // share cut a pull request's title to a third of the row while the repository
  // name beside it was cut to eight cells and said less.
  //
  // Every budget below is the cells the line actually holds: the status dot and
  // its gap, the one cell between the two halves of the row, the dots and the
  // cell before the figures, and the least a title keeps.
  const MIN_TITLE = 8;
  const right = fitSlots(rightSlots, Math.max(0, stacked ? resting - 2
    : resting - 2 - 1 - MIN_TITLE));
  const rightWidth = slotsWidth(right);
  // The checks sit beside the right slot, a cell from it, and take their room
  // before the dim middle text does: a dot is a verdict and the meta is context.
  const dotsRoom = stacked ? resting - 2 - rightWidth - 1
    : resting - 2 - 1 - rightWidth - 1 - MIN_TITLE;
  const dots = row.checks
    ? checkDots(row.checks.states, row.checks.more, Math.max(0, dotsRoom)) : null;
  const dotsWidth = dots ? dots.width + 1 : 0;
  // The dim middle text is context, and a long title is the row's name: where
  // both cannot be drawn, the name is kept and the context moves to the row's
  // hover card with the rest of what it says.
  const metaWanted = row.meta.length > 0 && !stacked
    && row.title.length <= Math.floor(resting * 0.55) ? 12 : 0;
  const titleRoom = stacked ? resting - 2
    : Math.max(MIN_TITLE, Math.min(row.title.length + (fill ? 2 : 0),
        resting - 2 - 1 - rightWidth - dotsWidth - (metaWanted ? metaWanted + 1 : 0)));
  const name = fit(row.title, titleRoom - (fill ? 2 : 0));
  const title = titleNode(row, name, fill);
  const titleWidth = name.length + (fill ? 2 : 0);
  const metaRoom = inner - 2 - 1 - rightWidth - dotsWidth - titleWidth;
  const meta = stacked || metaRoom < 6 ? [] : fitSlots(row.meta, metaRoom);
  const rightLine = dots
    ? box({ flexDirection: "row", gap: 1 }, right.length ? [dots.node, line(right)] : [dots.node])
    : line(right.length ? right : [{ text: "" }]);
  // A row holding more than its two lines says so on its figures: the words a
  // person already reads for the row's state are the press that opens them.
  const rightDrawn = row.detailsPress
    ? control(row.detailsPress, { plain: true, hover: { color: "claude" } }, [rightLine])
    : rightLine;
  const first = stacked
    ? box({ flexDirection: "row", gap: 1, flexGrow: 1 }, [statusDot(row.state ?? ""), title])
    : box({ flexDirection: "row", justifyContent: "space-between", gap: 1, flexGrow: 1 }, [
      box({ flexDirection: "row", gap: 1 }, [
        statusDot(row.state ?? ""),
        title,
        ...(meta.length ? [line(meta, { dimColor: true })] : []),
      ]),
      rightDrawn,
    ]);
  // The second line: the question an item waits on, or its bar and label.
  const room = Math.max(1, inner - 2);
  const asking = Boolean(row.detail) && (ASKING.has(row.state ?? "") || !row.bar);
  let second: Node | null = null;
  if (asking && row.detail) {
    // The row's own words are set in italic, so a reader tells what the work
    // said from what the pane measured.
    second = line([{ text: fit(row.detail, room) }],
                  { italic: true, ...(row.dim ? { dimColor: true } : {}) });
  } else if (row.bar) {
    second = barLine(row, room);
  }
  // What the row has to say beyond its two lines, shown while the pointer is on
  // it: a note on how its figures were read, and its own words when the bar
  // took the second line.
  const extra: Node[] = [];
  if (row.note && row.note.text) {
    extra.push(line([{ ...row.note, text: fit(row.note.text, room) }], { italic: true }));
  }
  if (row.detail && !asking) {
    extra.push(line([{ text: fit(row.detail, room) }], { italic: true }));
  }
  if (meta.length === 0 && row.meta.length && stacked) {
    extra.push(line(fitSlots(row.meta, room), { dimColor: true }));
  }
  const moved = offset > 0 ? { marginLeft: offset } : {};
  const railed = (glyph: string | null, content: Node, props: BoxProps = {}): Node => {
    const body = box({ flexDirection: "column", gap: 0, flexGrow: 1, ...moved }, [content]);
    const glyphs = glyph === null ? "" : (rail?.prefix ?? "") + glyph;
    return glyphs === ""
      ? box({ flexDirection: "row", gap: 0, ...props }, [body])
      : box({ flexDirection: "row", gap: 1, ...props }, [
        text({ color: rail?.color, ...(rail?.dim ? { dimColor: true } : {}) }, glyphs),
        body,
      ]);
  };
  const lines: Node[] = [railed(rail ? rail.first : null, first)];
  if (stacked && (right.length || dots)) {
    lines.push(railed(rail ? rail.rest : null, box({ marginLeft: 2, flexDirection: "row" },
                                                    [rightDrawn])));
  }
  if (second) {
    lines.push(railed(rail ? rail.rest : null, box({ marginLeft: 2, flexDirection: "row" },
                                                    [second])));
  }
  // The row's recent time, across the card under its bar: what it was doing
  // when, so a session that has sat idle for an hour reads as one at a glance.
  const strip = row.timeline ? timelineLine(row.timeline, room, row.dim === true) : null;
  if (strip) {
    lines.push(railed(rail ? rail.rest : null, box({ marginLeft: 2, flexDirection: "row" },
                                                    [strip])));
  }
  // The lines it draws at rest, under the first two: the subagent tasks a job
  // runs, the reply it suggests, what happens to a worktree next.
  for (const extraLine of row.lines ?? []) {
    const slots = fitSlots(extraLine.slots, room);
    const content = extraLine.press
      ? control(extraLine.press, { plain: true, hover: { color: "claude" } },
                inlineTexts(slots, extraLine.italic ? { italic: true } : {}))
      : line(slots, extraLine.italic ? { italic: true } : {});
    lines.push(railed(rail ? rail.rest : null,
                      box({ marginLeft: 2, flexDirection: "row" }, [content])));
  }
  // The row opened: what it holds in full, one dim line each, under the lines
  // it always draws. Nothing here is hidden behind the pointer, because a press
  // was the question and these are the answer.
  if (row.expanded && row.details?.length) {
    for (const detail of row.details) {
      lines.push(railed(rail ? rail.rest : null,
                        box({ marginLeft: 2, flexDirection: "row" },
                            [line([{ ...detail, text: fit(detail.text, room), dim: true }])])));
    }
  }
  if (row.field) {
    // The field is the row's last line, under what it answers.
    const field: Node = { type: "Input", props: { ...row.field }, children: [] };
    lines.push(railed(rail ? rail.rest : null,
                      box({ marginLeft: 2, flexDirection: "row" }, [field])));
  }
  if (extra.length) {
    lines.push(railed(rail ? rail.rest : null,
                      box({ marginLeft: 2, flexDirection: "column", gap: 0 }, extra),
                      { display: "none", hover: { display: "flex" } }));
  }
  // The row is a hover scope of its own: the pointer on it lights the title the
  // way the host lights the session under its cursor, and shows its extra lines.
  const address = key ?? row.key;
  // A row that failed is shaded in the theme's own soft red, so it stands out of
  // a section of healthy rows without being read first.
  const shaded = row.motion?.arriving ? { backgroundColor: "diffAddedDimmed" as const }
    : stateColor(row.state ?? "") === "error"
      ? { backgroundColor: "diffRemovedDimmed" as const } : {};
  // The row's whole words, drawn over it while the pointer is on it.
  //
  // The host draws no tooltip: a hover can restyle an element or reveal one
  // already in the tree, and nothing else. The title and the figures are each
  // cut to the line they share, and what a cut takes is exactly what tells two
  // similar rows apart. So the full line is written here, hidden and out of the
  // flow, and the row's own hover scope shows it over the row: nothing moves
  // when it appears, and it costs no room while it is away.
  const whole = hoverWords(row, rightSlots);
  if (whole !== "") {
    lines.push(box({ display: "none", position: "absolute", top: 0, left: 0,
                     hover: { display: "flex" }, backgroundColor: "diffAddedDimmed",
                     paddingX: 1, flexShrink: 0,
                     width: Math.min(resting, whole.length + 2) },
                   [text({ wrap: "truncate-end" }, whole)]));
  }
  return box({ ...(address ? { key: address } : {}), flexDirection: "column", gap: 0, ...shaded },
             lines);
}

/**
 * Everything a row says, uncut, for the card its hover draws.
 *
 * The title first and then its figures, which is the order they read in. A row
 * with nothing to say draws no card rather than an empty one.
 */
function hoverWords(row: Row, right: Slot[]): string {
  const figures = right.map((slot) => slot.text).join("").trim();
  return (row.title + row.meta.map((slot) => slot.text).join("")
          + (figures ? "  " + figures : "")).trim();
}

/**
 * A row's timeline as a strip of cells: its stretches, and the stretch from the
 * last of them to `to` in the state the row is in now, when it knows it.
 */
function timelineLine(timeline: Timeline, room: number, dim: boolean): Node | null {
  if (!timelineDrawn(timeline)) {
    return null;
  }
  const last = Math.max(...timeline.segments.map((segment) => segment.end));
  const stretches = timeline.tail && timeline.to > last
    ? [...timeline.segments, { start: last, end: timeline.to, state: timeline.tail }]
    : timeline.segments;
  return timelineStrip(stretches, timeline.from, timeline.to, room, dim);
}

/** Whether a timeline has anything to draw: a stretch, over a span of time. */
function timelineDrawn(timeline: Timeline | undefined): boolean {
  return timeline !== undefined && timeline.segments.length > 0 && timeline.to > timeline.from;
}

/**
 * A row's title: marked in its color when its state earns it, pressable when it
 * copies something, a link when it is a page, and quiet when the row is of the
 * past.
 *
 * A control holds texts and nothing else, so a mark inside one is its texts
 * rather than the box `tag` draws them in: the engine refuses a box in a
 * button, and the whole pane with it.
 */
function titleNode(row: Row, name: string, fill: Color | null): Node {
  const look: TextProps = row.dim ? { dimColor: true } : { bold: true };
  if (row.press) {
    const children = fill
      ? tagTexts(name, fill)
      : [text({ wrap: "truncate-end", ...look }, name)];
    return control(row.press, { plain: true, hover: { color: "claude" },
                                ...(row.dim ? { dimColor: true } : {}) }, children);
  }
  if (row.link) {
    // A link is inline, so a marked title is the mark's texts inside the link,
    // kept from shrinking as the mark's own box keeps them: a failing pull
    // request is still a page a person opens.
    const inline = fill
      ? tagTexts(name, fill)
      : [text({ wrap: "truncate-end", ...look, hover: { color: "claude" } }, name)];
    const link: Node = { type: "Link", props: { href: row.link }, children: inline };
    return fill ? box({ flexDirection: "row", gap: 0, flexShrink: 0 }, [link]) : link;
  }
  return fill
    ? tag(name, fill)
    : text({ wrap: "truncate-end", ...look, hover: { color: "claude" } }, name);
}

/** Slots as the texts a control may hold, spaced as `line` spaces them. */
function inlineTexts(slots: Slot[], props: TextProps = {}): Node[] {
  return slots.map((slot, index) => text(
    { ...props, ...slotProps(slot) },
    index === 0 || slot.text.startsWith(" ") ? slot.text : " " + slot.text));
}

/** How many cells a run of slots draws, with the spaces `line` puts between them. */
function slotsWidth(slots: Slot[]): number {
  return slots.reduce((sum, slot, index) =>
    sum + slot.text.length + (index === 0 || slot.text.startsWith(" ") ? 0 : 1), 0);
}

/**
 * A row's bar and the words for it, on one line.
 *
 * A label the caller wrote is drawn instead of the counts, and no label at all
 * is drawn as nothing: the failure and stop tails belong to the computed label,
 * because a caller that writes its own has already said both. The bar takes the
 * line the label leaves, or the length the configuration fixes when that is
 * shorter. Counts that cannot be drawn as a bar are stated instead.
 */
function barLine(row: Row, room: number): Node {
  const bar = row.bar as Bar;
  const counts: Slot[] = bar.label === null ? []
    : bar.label !== undefined ? [bar.label]
      : [countLabel(bar),
         ...((bar.failed ?? 0) > 0
           ? [{ text: ` ${SEPARATOR} ${bar.failed} failed`, color: "error" as const }] : []),
         ...(bar.stopped ? [{ text: ` ${SEPARATOR} Stopped early`, color: "warning" as const }]
           : [])];
  const label = fitSlots(counts, Math.max(0, Math.floor(room / 2)));
  const labelWidth = slotsWidth(label);
  const free = Math.max(1, room - (label.length ? labelWidth + 2 : 0));
  const length = bar.cells === undefined ? free : Math.min(free, bar.cells);
  const cells = rateBar(bar.done, bar.total,
                        (bar.failed ?? 0) > 0 ? "error" : stateTone(row.state), length);
  if (!cells) {
    return line([countLabel(bar)]);
  }
  // The drawing's alt says what the label beside it says, so a waiting bar is
  // read as its time left rather than as two counts of seconds.
  const spoken = label.map((slot) => slot.text.trim()).filter(Boolean).join(" ");
  const drawn = cells.vector && spoken ? { ...cells, vector: { ...cells.vector, alt: spoken } }
    : cells;
  return label.length ? box({ flexDirection: "row", gap: 2 }, [drawn, line(label)]) : drawn;
}

/**
 * What names a section among its siblings: its fold control's address, which
 * carries the section's id, or its title when it has no control.
 *
 * Two sections may be given the same title by configuration, and siblings that
 * share a key are not hover scopes at all, so the title alone is not enough.
 */
export function groupKey(group: Group): string {
  return group.toggle?.key ?? group.title;
}

/** The bar's color for a row in a state: its own, or the healthy one. */
function stateTone(state: string | undefined): Color {
  const tone = stateColor(state ?? "");
  return tone === "subtle" ? "success" : tone;
}

/**
 * The color a card's rule is drawn in: the loudest thing inside it.
 *
 * A broken source is the error color, a stale or unread one and a card holding
 * something that waits on a person are the warning color, and a card with live
 * work is the success color. Everything else is the quiet rule. The rule repeats
 * what the card's heading and rows already say in words; it is how a person
 * finds the card that needs them before reading any of it.
 */
export function groupTone(group: Group): Color {
  if (group.state === "failed") {
    return "error";
  }
  if (group.state === "unavailable" || group.state === "stale") {
    return "warning";
  }
  const tones = group.rows.map((row) => stateColor(row.state ?? ""));
  if (tones.includes("error")) {
    return "error";
  }
  if (tones.includes("warning")) {
    return "warning";
  }
  if (tones.includes("success")) {
    return "success";
  }
  return "subtle";
}

/**
 * One group: a card, with its heading, its rows and the state it is in.
 *
 * The card is a bordered box the surface draws, so a run of sections reads as
 * tiles rather than as headings stacked over rows. The heading carries a mark
 * for the fold, the section's name, and what it holds at the right; the mark is
 * on the control itself, so it is a thing a person presses rather than a word
 * beside one.
 *
 * A collapsed group keeps its heading and its count, and a group that failed
 * keeps its warning line: an error hidden behind a folded card is a claim that
 * nothing is wrong, which is the one thing this design will not do.
 */
export function renderGroup(given: Group, width: number, narrowAt: number,
                            surface = "terminal"): Node {
  // A picture surface is drawn as cards: a rounded rule round each section and
  // air inside it, which is what a person expects of a panel rather than of a
  // run of terminal lines. The rule and the padding take four columns, two more
  // than the terminal's padding alone, so the section holds four fewer.
  const graphical = surface !== "terminal";
  // A row arriving while another leaves takes its place: drawn together for the
  // length of the slide, the section grew by the leaving row and shrank back,
  // and every section below it went down and up. With nothing arriving, a
  // leaving row slides out where it stood.
  const group = given.rows.some((entry) => entry.motion?.arriving)
    ? { ...given, rows: given.rows.filter((entry) => !entry.motion?.leaving) } : given;
  // The rule and the padding take four columns from the width the pane was
  // given, so what the card holds is four less. Budgeting two less left the
  // contents two columns wider than the card draws, and the padding each row
  // added took it to four.
  const inner = Math.max(8, width - (graphical ? 4 : 2));
  // The section's name is drawn in the tone its card is drawn in, behind the
  // accent, so a person finds the section that needs them by its color before
  // reading a word of it. It is on no fill: a column of names on blocks of
  // yellow and green outshouted the counts they head. The accent and its space
  // take the two cells the chip's fill took, so the name is cut as it was.
  const tone = groupTone(group);
  // New warnings blink: the heading and the rail swap between the warning and
  // the error color for a few seconds, then hold the section's own tone.
  const shown: Color = group.blink === undefined ? tone : group.blink ? "warning" : "error";
  // A calm section's rail, and on a picture surface its card rule, rests dim; a
  // section that warns is drawn at full strength.
  const calm = group.blink === undefined && (tone === "subtle" || tone === "success");
  // The mark is texts and no box: a button holds strings and text only, and the
  // engine refuses a heading that puts a box inside its fold control.
  const named = (room: number): Node[] => tagTexts(fit(group.title, room), shown);
  const titleRoom = Math.max(8, inner - 10);
  const shownTitle = fit(group.title, titleRoom);
  const heading = group.toggle
    ? control(group.toggle, { plain: true }, named(titleRoom))
    : box({ flexDirection: "row", gap: 0, flexShrink: 0 }, named(Math.max(8, inner - 6)));
  // What the heading takes before the figures get their room: the fold mark and
  // its gap, the three cells a control gives its hotkey, the accent and its
  // space, and the title as it is actually drawn. The title is fitted first
  // because a cut title leaves the figures the room its unshown length was
  // costing them; and the one cell between the two halves of the line is
  // counted because a summary budgeted without it was a cell too wide, which is
  // how "9 merged" ended up wrapped under its own count.
  const leftCells = 2 + (group.toggle?.hotkey ? group.toggle.hotkey.length + 2 : 0)
    + 2 + shownTitle.length;
  const summaryRoom = Math.max(0, inner - leftCells - 1);
  const parts: Node[] = [
    box({ flexDirection: "row", justifyContent: "space-between", gap: 1 }, [
      box({ flexDirection: "row", gap: 1, flexShrink: 0 }, [
        text({ color: group.state === "failed" ? "error" : "subtle" },
             group.collapsed ? FOLDED : OPENED),
        heading,
      ]),
      summaryLine(fittedSummary(group, summaryRoom)),
    ]),
  ];
  // The legend is what the section's counts mean, so it is drawn with the rows
  // rather than with the heading: a folded section states its counts and does
  // not explain them, which is what folding it asked for. A section drawn as one
  // line draws none either, because there is nothing under it to explain: a
  // legend over an empty section is the second line that drawing it as a line
  // was meant to save.
  //
  // It is the card's hint rather than its content, so it shows while the pointer
  // is on the card and hides at rest: the surface does the showing, and a reader
  // who never points keeps that line for rows.
  if (group.legend && !group.collapsed && boxed(group)) {
    parts.push(box({ display: "none", hover: { display: "flex" } },
                   [line([{ text: fit(group.legend, inner), dim: true }], { italic: true })]));
  }
  // The tiles head the section's rows, as the Agents panel heads a run with its
  // figures. Folding gives their room back, like everything under the heading.
  if (group.tiles && group.tiles.length && !group.collapsed) {
    parts.push(renderTiles(group.tiles, inner));
  }
  // The strip says how the recent past went, which is what a reader looks for
  // before reading a single row, so it sits above them. It is not drawn for a
  // folded section: folding gave that room back.
  if (group.history && !group.collapsed) {
    const strip = historyStrip(group.history, inner);
    if (strip) {
      parts.push(strip);
    }
  }
  // What the section's work cost over the window, under the heading for the
  // same reason the strip is: no single row is the day.
  if (group.spark && !group.collapsed) {
    const spark = sparkLine(group.spark, inner);
    if (spark) {
      parts.push(spark);
    }
  }
  // The columns are named once, above the rows they align with, in the same
  // dim tone as any other label. A folded section draws none: it draws no rows.
  if (group.columns?.length && group.rows.length && !group.collapsed) {
    parts.push(box({ flexDirection: "row", justifyContent: "flex-end" },
                   [line(group.columns.map((slot): Slot => ({ ...slot, dim: true })))]));
  }
  if (group.rows.length && !group.collapsed) {
    // The section is the parent and its items hang off one rail in its tone. A
    // calm rail rests dim; one that warns is drawn at full strength.
    const count = group.rows.length;
    // A section drawn as a tree prints each project root once, in the theme's
    // accent, and hangs that project's rows one rail deeper: the section's own
    // rail holds each root, and the root's rail runs on when another project
    // follows it.
    const drawn: Node[] = [];
    group.rows.forEach((row, index) => {
      const project = row.project;
      const newProject = project !== undefined
        && (index === 0 || group.rows[index - 1]?.project?.root !== project.root);
      if (newProject && project) {
        const rail: Rail = {
          first: project.last ? RAIL_LAST : RAIL_BRANCH,
          rest: project.last ? RAIL_END : RAIL_ON,
          color: shown, ...(calm ? { dim: true } : {}),
        };
        drawn.push(renderProject(project, inner, graphical ? undefined : rail));
      }
      const next = group.rows[index + 1];
      // A row without a project closes its own rail at the section's end; a
      // row inside a project closes when its project has no next row.
      const closesRail = project === undefined
        ? index === count - 1
        : next?.project?.root !== project.root;
      const lastChild = closesRail;
      const first = lastChild ? RAIL_LAST : RAIL_BRANCH;
      const rest = lastChild ? RAIL_END : RAIL_ON;
      const prefix = project === undefined ? "" : project.last ? RAIL_END : RAIL_ON;
      drawn.push(renderRow(
        row, inner, narrowAt,
        "row:" + groupKey(group) + ":" + (row.key ?? String(index)),
        graphical ? undefined
          : { first, rest, prefix, color: shown, ...(calm ? { dim: true } : {}) }));
    });
    parts.push(box({ flexDirection: "column", gap: 0 }, drawn));
    // What the ceiling held back is drawn under the section while the pointer is
    // on it: the heading already states how many there are, and a number a
    // person cannot open is one they have to take on trust. The rows are read
    // and masked exactly as the drawn ones are, so this shows nothing new.
    if (group.held && group.held.length) {
      const heldCount = group.held.length;
      parts.push(box({ display: "none", hover: { display: "flex" },
                       flexDirection: "column", gap: 0 },
                     group.held.map((row, index) => renderRow(
                       row, inner, narrowAt,
                       "held:" + groupKey(group) + ":" + (row.key ?? String(index)),
                       graphical ? undefined
                         : { first: index === heldCount - 1 ? RAIL_LAST : RAIL_BRANCH,
                             rest: index === heldCount - 1 ? RAIL_END : RAIL_ON,
                             color: shown, ...(calm ? { dim: true } : {}) }))));
    }
  }
  // A row still sliding out is still on the pane, so a section is not yet
  // empty: said under the leaving row, the line jumped up a row when it went.
  // A failure is said at once, whatever is moving.
  const leaving = group.rows.some((entry) => entry.motion?.leaving);
  if ((!group.rows.length || group.state !== "ready")
      && (!leaving || group.state === "failed" || group.state === "stale")) {
    const message = groupMessage(group);
    if (message.length) {
      parts.push(line(message));
    }
  }
  // What the section knows beyond its rows, while it is open: a folded section
  // gave its room back, notes included.
  if (group.notes && group.notes.length && !group.collapsed) {
    for (const note of group.notes) {
      parts.push(line(fitSlots(note, inner)));
    }
  }
  if (group.reserve && !group.collapsed) {
    // A part that shows only under the pointer, as a legend does, takes no
    // room at rest, so it makes up none of the reserve.
    const showing = parts.slice(1).filter((part) =>
      (part as { props?: { display?: string } }).props?.display !== "none").length;
    const held = bodyLines(group, showing);
    for (let blank = held; blank < group.reserve; blank += 1) {
      parts.push(line([{ text: "" }]));
    }
  }
  // No card border in a terminal: the heading's chip and the rail its items hang
  // off are what group a section, and the border's two lines and four columns go
  // to the rows. A picture surface has the room and a panel's expectations, so
  // there each section is a rounded card with air inside it, and its rule is
  // drawn dim while the section is calm.
  return box({ key: "group:" + groupKey(group), flexDirection: "column", gap: 0, width,
               marginBottom: 1, paddingX: 1,
               ...(graphical
                 ? { borderStyle: "round" as const, paddingY: 1,
                     ...(calm ? { borderDimColor: true } : { borderColor: shown }) }
                 : {}) }, parts);
}

/**
 * The lines a section's body takes at rest: each of its parts but the rows is
 * one line, and each row is its first line and, when it has one, its second
 * (the bar, or the question it waits on). The lines a row shows only under the
 * pointer are not counted, since at rest they take no room.
 */
function bodyLines(group: Group, parts: number): number {
  if (!group.rows.length) {
    return parts;
  }
  const rows = group.rows.reduce((sum, entry) => {
    const asking = Boolean(entry.detail) && (ASKING.has(entry.state ?? "") || !entry.bar);
    return sum + 1 + (entry.bar || asking ? 1 : 0) + (timelineDrawn(entry.timeline) ? 1 : 0);
  }, 0);
  // The rows are one part of the body, drawn as many lines.
  return parts - 1 + rows;
}

/**
 * A series and its label on one line: the glyphs take what the label leaves, and
 * the label is cut to half the line first, so a long one never squeezes the
 * series to nothing; the segments it keeps whole are the exception, and a line
 * with no room left for the series is the label alone.
 */
function sparkLine(spark: Spark, width: number): Node | null {
  const label = sparkLabel(spark, width);
  const room = width - (label.length ? slotsWidth(label) + 2 : 0);
  const glyphs = sparkline(spark.values, room);
  if (!glyphs) {
    return label.length ? line(label) : null;
  }
  return label.length ? box({ flexDirection: "row", gap: 2 }, [glyphs, line(label)]) : glyphs;
}

/**
 * A spark's label cut to its share of the line, the segments it keeps whole set
 * apart from the rest: cut as one line, the mark that says the rest was dropped
 * would be cut into the last kept segment, which is the one that had to stay.
 */
function sparkLabel(spark: Spark, width: number): Slot[] {
  const kept = spark.label.slice(0, spark.keep ?? 0);
  const keptWidth = slotsWidth(kept);
  const share = Math.max(0, Math.floor(width / 2));
  if (!kept.length || keptWidth > width) {
    return fitSlots(spark.label, share);
  }
  const rest = spark.label.slice(kept.length);
  return [...kept, ...fitSlots(rest, Math.max(share, keptWidth) - keptWidth)];
}

/**
 * The digest: a heading in its tone and a line per event, each cut to the
 * pane's width, indented under the heading as a section's rows are.
 */
function digestBlock(digest: Digest, width: number): Node {
  const title = fit(digest.title, Math.max(8, width - 4));
  const heading = fitSlots(digest.heading, Math.max(0, width - title.length - 3));
  return box({ key: "digest", flexDirection: "column", gap: 0, marginTop: 1, paddingX: 1 }, [
    box({ flexDirection: "row", gap: 1 }, [
      box({ flexDirection: "row", gap: 0, flexShrink: 0 }, tagTexts(title, digest.tone)),
      ...(heading.length ? [line(heading)] : []),
    ]),
    ...digest.lines.map((slots) => box({ marginLeft: 2, flexDirection: "row" },
                                       [line(fitSlots(slots, Math.max(0, width - 4)))])),
  ]);
}

/** Below this a tile cannot hold a figure and its label, so tiles stack. */
const TILE_MINIMUM = 12;

/**
 * A section's tiles side by side, each its share of the width, or one under
 * another when the card is too narrow for that: a figure cut to fit is a figure
 * nobody can read.
 *
 * Each tile carries a vector drawing of the same words, cut the same way, which
 * a surface that draws vectors shows as a card in place of the bordered box.
 */
function renderTiles(tiles: Tile[], width: number): Node {
  const across = Math.floor((width - (tiles.length - 1)) / tiles.length);
  const stacked = across < TILE_MINIMUM;
  const each = stacked ? width : across;
  return box({ flexDirection: stacked ? "column" : "row", gap: stacked ? 0 : 1 },
             tiles.map((tile) => {
               const label = fit(tile.label, Math.max(4, each - 4));
               const value = fit(tile.value, Math.max(4, each - 4));
               const color = tile.color ?? "text";
               // The drawing is handed the whole words and cuts them by its own
               // measure, since a proportional face is not a cell wide a letter.
               return {
                 ...box({
                   flexDirection: "column", gap: 0, borderStyle: "round", borderColor: "subtle",
                   borderDimColor: true, paddingX: 1, width: each,
                 }, [text({ dimColor: true }, label), text({ bold: true, color }, value)]),
                 vector: tileVector(tile.label, tile.value, color, each),
               };
             }));
}

/**
 * A section's counts, cut to the room the heading leaves them.
 *
 * A heading's figures are the tail of a line that already holds the section's
 * name, so a section with five of them runs past the edge of the pane, and what
 * a reader loses is the last figure and the rule around it. Cutting here marks
 * the loss where it happened rather than letting the surface decide, and the
 * figures are cut from the least important end because the callers write them
 * most-important-first.
 */
function fittedSummary(group: Group, room: number): Slot[] {
  // A heading already too long to leave its figures any room is the case this
  // exists for, not the case it skips: returning the figures whole drew them
  // uncut across a card they did not fit in.
  return fitSlots(group.summary, Math.max(0, room), true);
}

/**
 * A line of segments cut to a width from its end, each segment keeping its own
 * style.
 *
 * Callers write their segments most important first, so the cut falls on the
 * least important. A segment the cut lands in is ended with the truncation mark
 * where a few cells of it still read; on a line drawn with chips (`chips`), a
 * segment drawn as a chip is dropped whole instead, because half a count on a
 * fill reads as a different count. Cutting
 * here rather than leaving it to the surface matters: a row of texts too wide
 * for its line is squeezed segment by segment, and every segment wraps into a
 * column of its own.
 */
export function fitSlots(slots: Slot[], room: number, chips = false): Slot[] {
  const out: Slot[] = [];
  let used = 0;
  // Only a line drawn as a summary draws its colored counts as chips; every
  // other line draws them as colored text, which is cut like any text. Measured
  // as a chip there, a warning was dropped whole for want of a cell it never
  // needed, and the line lost the one word it was there to say.
  const isChip = (slot: Slot): boolean =>
    chips && slot.color !== undefined && !slot.dim && CHIP_TONES.has(slot.color);
  const mark = " " + TRUNCATION;
  // A slot that holds a column is padded to that column before anything is
  // measured, so what follows starts where the column ends rather than where
  // this row's figure happened to stop.
  const placed = (slot: Slot): Slot => slot.width === undefined ? slot
    : { ...slot, text: slot.align === "left"
        ? slot.text.padEnd(slot.width) : slot.text.padStart(slot.width) };
  for (const [index, slot] of slots.entries()) {
    const column = placed(slot).text;
    const shown = index === 0 || column.startsWith(" ") ? column : " " + column;
    const chipped = isChip(slot);
    // A chip is drawn as its trimmed word with a cell of fill at each side.
    const drawn = chipped ? slot.text.trim().length + 2 + (index === 0 ? 0 : 1) : shown.length;
    if (used + drawn <= room) {
      out.push(placed(slot));
      used += drawn;
      continue;
    }
    const left = room - used;
    if (!chipped && left > TRUNCATION.length + 2) {
      out.push({ ...slot, text: cutToWord(shown, left) });
      break;
    }
    // No room for any of this segment, so the line says it was cut rather than
    // ending there: the mark is its own dim segment when it fits, and otherwise
    // goes on the plain text before it. A chip is never marked, because its fill
    // would carry the mark as though it were part of the figure; a line that
    // ends on a chip with no room left keeps the figure and goes unmarked, since
    // a count is worth more than the news that something followed it.
    const last = out.at(-1);
    if (last !== undefined && room - used >= mark.length) {
      out.push({ text: mark, dim: true });
    } else if (last !== undefined && !isChip(last)) {
      const keep = Math.max(0, last.text.length - TRUNCATION.length);
      out[out.length - 1] = { ...last, text: last.text.slice(0, keep) + TRUNCATION };
    }
    break;
  }
  return out;
}

/**
 * Whether a section earns a card, or is stated as one line.
 *
 * Something inside it, or something wrong with it: those are the two reasons a
 * section is drawn as a box. Everything else is a heading and its count, which
 * is what a reader needs and no more.
 */
export function boxed(group: Group): boolean {
  if (group.rows.length || (group.notes?.length ?? 0) > 0) {
    return true;
  }
  return group.state === "failed" || group.state === "unavailable"
    || group.state === "stale";
}

/** What a press may hold: strings and Text, with a box unwrapped into them.
 *
 * The host draws a Button's content as words and refuses any other child, and
 * a refused Button throws where the pane is being drawn: the whole render is
 * lost and the person sees an empty frame. A row's press is built from a box
 * around its figures, so the box is taken apart here and only its words are
 * kept. Nothing is lost that a press can hold in the first place.
 */
export function pressable(children: (Node | string)[]): (Node | string)[] {
  const out: (Node | string)[] = [];
  for (const child of children) {
    if (typeof child === "string") {
      out.push(child);
      continue;
    }
    if (child.type === "Box") {
      out.push(...pressable(child.children));
      continue;
    }
    if (child.type === "Text") {
      out.push(child);
    }
  }
  return out;
}

/** A pressable control, drawn with the label the pane gave it. */
function control(item: Control,
                 props: Omit<ButtonProps, "key" | "label" | "onPress"> = {},
                 children: Node[] = []): Node {
  // No hover: the host draws a hover only under a keyed Box, and a Button with
  // one and no such box above it is refused, taking the whole pane with it.
  // The tint comes back when the row a press sits in carries a key.
  const { hover: _hover, ...rest } = props as { hover?: unknown };
  return {
    type: "Button",
    props: { key: item.key, label: item.label, onPress: item.onPress,
             hotkey: item.hotkey, dimColor: item.dim, ...rest },
    children: pressable(children),
  };
}

/** The colors a count is drawn on a chip in: the states, not the accents. */
const CHIP_TONES = new Set<Color>(["success", "warning", "error", "merged"]);

/**
 * A section's counts: a count of a state marked in its color, and every other
 * figure as plain text.
 *
 * A count the pane colored is a state (waiting, failed), and the accent is how
 * a state is drawn everywhere else on the pane; a dim figure such as a cost is
 * a measurement, and a measurement drawn as a state would read as an alarm.
 */
function summaryLine(slots: Slot[]): Node {
  return box({ flexDirection: "row", gap: 0 }, slots.map((slot, index) => {
    if (slot.color && !slot.dim && CHIP_TONES.has(slot.color)) {
      const parts = index === 0 ? [] : [text({}, " ")];
      return box({ flexDirection: "row", gap: 0 }, [...parts, tag(slot.text.trim(), slot.color)]);
    }
    return text(slotProps(slot),
                index === 0 || slot.text.startsWith(" ") ? slot.text : " " + slot.text);
  }));
}

/**
 * The picker's lines: one control per section the configuration made visible.
 *
 * The names wrap rather than leaving the width: a picker that dropped the
 * sections past the pane's edge would be one a person could not use to bring
 * back the section that was cut.
 */
function pickerRows(picker: PickerItem[], width: number): Node[] {
  const rows: Node[] = [];
  const gap = 2;
  const room = Math.max(1, width);
  let row: Node[] = [];
  let used = 0;
  for (const item of picker) {
    // A title wider than the pane is cut: a control wider than the pane would
    // push every control after it off the line.
    const title = fit(item.title, room);
    if (row.length > 0 && used + gap + title.length > room) {
      rows.push(box({ flexDirection: "row", gap }, row));
      row = [];
      used = 0;
    }
    row.push(control(item.press,
                     { plain: true, ...(item.hidden ? { dimColor: true } : {}) },
                     [text(item.hidden ? { dimColor: true } : {}, title)]));
    used += (row.length > 1 ? gap : 0) + title.length;
  }
  if (row.length > 0) {
    rows.push(box({ flexDirection: "row", gap }, row));
  }
  return rows;
}

/** The whole pane, in reading order. */
export function renderPane(pane: Pane, surface = "terminal"): Tree {
  // The title is a chip in the host's own accent, the mark the pane is known by
  // at a glance; the age beside it is set in italic, as a note on the reading
  // rather than a figure of it.
  //
  // The head is as short as it can be made, because an inline pane is given a
  // fixed number of rows and every row the head takes is a row of a card cut
  // off below. The figures share the title's line when they fit beside it, and
  // take a line of their own when they do not; the controls take one more.
  // The product's name, marked as itself rather than as a status chip. A fill
  // on the name read as one more state beside the figures, and the name is the
  // one thing in the head that is not a reading. The mark is the brand's bar
  // and dot in two cells; the width arithmetic below counts them with the gap
  // that separates them from the word.
  const MARK = "▬●";
  const title = box({ flexDirection: "row", gap: 1, flexShrink: 0 }, [
    text({ color: "success" }, MARK),
    text({ bold: true }, fit(pane.title, Math.max(8, pane.width - 24 - MARK.length))),
  ]);
  const age = line([pane.updated, ...(pane.warning ? [pane.warning] : [])], { italic: true });
  const ageWidth = pane.updated.text.length + (pane.warning ? pane.warning.text.length + 1 : 0);
  // One statement of the figures, never two. The cards are the form a person
  // reads at a glance and the line is the form that survives when there is
  // nothing to put in a card: a pane whose roster could not be read draws no
  // cards, and it still says what it does know rather than saying it twice.
  const cards = pane.cards ?? [];
  const cardsWidth = cards.reduce((sum, card) => sum + card.value.length + card.label.length + 3, 0)
    + 3 * Math.max(0, cards.length - 1);
  const beside = cards.length > 0
    && pane.title.length + MARK.length + 1 + 3 + cardsWidth + 2 + ageWidth <= pane.width;
  const parts: Node[] = [
    box({ flexDirection: "row", justifyContent: "space-between", gap: 1 }, [
      beside ? box({ flexDirection: "row", gap: 3 }, [title, statStrip(cards, cardsWidth, true)])
             : title,
      age,
    ]),
  ];
  if (!beside) {
    parts.push(cards.length ? statStrip(cards, pane.width) : line(pane.counts));
  }
  // The controls are drawn the way the host draws its own shortcuts: the key in
  // the accent color, then the word, with no bracket chrome round each one.
  if (pane.controls?.length) {
    // The hint shares the controls' line, so it is said only where the line has
    // room for it: the host draws each keyed control as its key, a colon and a
    // space before its label, and three cells part them. A narrower pane drops
    // the hint rather than wrapping the controls under it.
    const used = pane.controls.reduce((sum, item) =>
      sum + item.label.length + (item.hotkey ? 3 : 0), 0) + 3 * (pane.controls.length - 1);
    const hint = pane.hint && used + 3 + pane.hint.length <= pane.width ? pane.hint : null;
    parts.push(box({ flexDirection: "row", gap: 3 }, [
      ...pane.controls.map((item) => control(item,
        { dimColor: true, ...(item.hotkey ? { plain: true as const } : {}) })),
      ...(hint ? [text({ dimColor: true, italic: true }, hint)] : []),
    ]));
  }
  // The picker: the sections a person may put away, and the ones already put
  // away, named dim so the same press brings them back. It sits under the
  // controls and above everything that narrows or filters, so it is always the
  // way back to a section, whatever else the pane is doing.
  if (pane.picker?.length) {
    parts.push(...pickerRows(pane.picker, pane.width));
  }
  // A narrowed pane says so, with the press that widens it again: the figures
  // above still count the whole machine, and a person who forgot the press
  // would read a filtered list as a quiet fleet.
  if (pane.focus) {
    parts.push(box({ flexDirection: "row", gap: 2 }, [
      text({ dimColor: true }, pane.focus.text),
      control(pane.focus.clear,
              { plain: true, dimColor: true, hover: { color: "claude" } },
              [text({ dimColor: true, italic: true }, pane.focus.clear.label)]),
    ]));
  }
  // What happened while the person was away heads the sections, since it is
  // the first thing a person coming back wants, and it is gone when nothing is.
  if (pane.digest) {
    parts.push(digestBlock(pane.digest, pane.width));
  }
  // One empty row between the head and the first card, and no more.
  parts.push(box({ flexDirection: "column", gap: 0, marginBottom: 1 }, []));
  for (const group of pane.groups) {
    parts.push(renderGroup(group, pane.width, pane.narrowAt, surface));
  }
  // The footer is the pane's one line of identity, under everything it reports:
  // a person reading a screenshot or quoting a version in a report takes it
  // from here, not from a header that competes with the counts.
  if (pane.footer) {
    parts.push(box({ flexDirection: "row", marginTop: 1 }, [
      text({ dimColor: true }, fit(pane.footer.text, pane.width)),
    ]));
  }
  return box({ flexDirection: "column", gap: 0 }, parts);
}

/** Every element type a tree uses, so a test can prove only Box and Text appear. */
export function elementTypes(tree: Tree): string[] {
  const found = new Set<string>();
  const walk = (node: Node | string): void => {
    if (typeof node === "string") {
      return;
    }
    found.add(node.type);
    for (const child of node.children) {
      walk(child);
    }
  };
  walk(tree);
  return [...found].sort();
}

/** The plain strings a tree holds, in order, for asserting what a person reads. */
/**
 * Whether a node is a row's hover card.
 *
 * A card is out of the flow and hidden at rest, so it takes no cells and draws
 * nothing until the pointer is on the row it belongs to. Anything measuring
 * what a row draws leaves it out.
 */
export function isHoverCard(node: Node): boolean {
  const props = node.props as { display?: unknown; position?: unknown };
  return props.display === "none" && props.position === "absolute";
}

export function renderedText(tree: Tree): string[] {
  const values: string[] = [];
  const walk = (node: Node | string): void => {
    if (typeof node === "string") {
      values.push(node);
      return;
    }
    // A card held out of the flow and hidden is not part of what the pane
    // draws: it is drawn only while the pointer is on the row it belongs to,
    // and it repeats words that row already shows. A hidden line still in the
    // flow is drawn here, because hovering reveals it in the row's own place.
    if (isHoverCard(node)) {
      return;
    }
    // A button draws its label, and a label is text on the screen like any
    // other. A check that reads what a tree shows has to see it, or every
    // section heading would read as missing the moment it became pressable.
    const label = (node.props as { label?: unknown }).label;
    if (node.type === "Button" && typeof label === "string") {
      values.push(label);
    }
    for (const child of node.children) {
      walk(child);
    }
  };
  walk(tree);
  return values;
}

files.components/speech.ts:
/**
 * The voice: which one speaks, and what `/speak` asks for.
 *
 * The voices come from the configuration, through the helper that resolves it,
 * because a plugin has no configuration file of its own to read. What a person
 * picks with `/speak` is theirs, kept in the plugin's store across sessions:
 * on or off, a group, and optionally one voice by name.
 *
 * Every voice is a local synthesized one that writes a file the engine plays.
 * The platform's own synthesizer is never used: asked for a voice it does not
 * have, it speaks in its default without saying so, and a person who picked a
 * natural voice would hear a robotic one instead.
 */

export type VoiceKind = "female" | "male";
export type Voices = Record<VoiceKind, string[]>;

/** What a person picked: whether the fleet speaks, which group, and which voice in it. */
export type VoiceSetting = { isOn: boolean; voice: VoiceKind; name?: string };

/** What the helper says about speech on this machine. */
export type SpeechInfo = {
  state: "ready" | "unavailable";
  reason: string | null;
  group: VoiceKind;
  voice: string | null;
  voices: Voices;
};

export const SPEAK_USAGE = "/speak on, off, female, male, list, or a voice name.";

const KINDS: VoiceKind[] = ["female", "male"];

function isKind(value: unknown): value is VoiceKind {
  return value === "female" || value === "male";
}

/** The helper's answer, or null for anything that is not one. */
export function speechInfo(stdout: string): SpeechInfo | null {
  let value: unknown;
  try {
    value = JSON.parse(stdout);
  } catch {
    return null;
  }
  if (typeof value !== "object" || value === null) {
    return null;
  }
  const info = value as Record<string, unknown>;
  const raw = info.voices as Record<string, unknown> | undefined;
  if ((info.state !== "ready" && info.state !== "unavailable") || !isKind(info.group)
      || typeof raw !== "object" || raw === null) {
    return null;
  }
  const voices: Voices = { female: [], male: [] };
  for (const kind of KINDS) {
    const list = raw[kind];
    voices[kind] = Array.isArray(list) ? list.filter((name): name is string => typeof name === "string") : [];
  }
  return {
    state: info.state,
    reason: typeof info.reason === "string" ? info.reason : null,
    group: info.group,
    voice: typeof info.voice === "string" ? info.voice : null,
    voices,
  };
}

/**
 * What a stored value says, or the configuration's own choice for anything it
 * cannot be. A voice the configuration no longer lists is dropped, so a sample
 * removed from the list stops being picked.
 */
export function voiceSetting(stored: unknown, info: SpeechInfo): VoiceSetting {
  const fallback: VoiceSetting = {
    isOn: true, voice: info.group,
    ...(info.voice !== null && info.voices[info.group].includes(info.voice) ? { name: info.voice } : {}),
  };
  if (typeof stored !== "object" || stored === null) {
    return fallback;
  }
  const value = stored as { isOn?: unknown; voice?: unknown; name?: unknown };
  const voice = isKind(value.voice) ? value.voice : fallback.voice;
  const name = typeof value.name === "string" && info.voices[voice].includes(value.name)
    ? value.name : voice === fallback.voice ? fallback.name : undefined;
  return {
    isOn: typeof value.isOn === "boolean" ? value.isOn : fallback.isOn,
    voice,
    ...(name !== undefined ? { name } : {}),
  };
}

/** What `/speak <args>` asks for: a new setting, the status, the list, or nothing it knows. */
export function speakRequest(args: string, current: VoiceSetting,
                             voices: Voices): VoiceSetting | "status" | "list" | null {
  const text = args.trim().toLowerCase();
  if (text === "") {
    return "status";
  }
  let isOn: boolean | undefined;
  let selection: VoiceSetting | undefined;
  let selectedWord: string | undefined;
  let list = false;
  for (const word of text.split(/\s+/)) {
    if (word === "list") {
      list = true;
    } else if (word === "on" || word === "off") {
      const requested = word === "on";
      // Refused rather than last-word-wins, which would make the meaning hang
      // on the order the words were typed in.
      if (isOn !== undefined && isOn !== requested) {
        return null;
      }
      isOn = requested;
    } else {
      const voice = KINDS.find((kind) => word === kind || voices[kind].includes(word));
      if (voice === undefined) {
        return null;
      }
      if (selectedWord !== undefined && selectedWord !== word) {
        return null;
      }
      selectedWord = word;
      selection = { isOn: true, voice, ...(word === voice ? {} : { name: word }) };
    }
  }
  // Picking a voice switches speech on, so off with a pick asks for both.
  if (isOn === false && selection !== undefined) {
    return null;
  }
  if (list) {
    return "list";
  }
  const setting = selection ?? current;
  return { ...setting, isOn: isOn ?? setting.isOn };
}

/** The voices to try, in order: the one that spoke last, the pick, then the rest of the group. */
export function voiceOrder(setting: VoiceSetting, last: string | null, voices: Voices): string[] {
  const group = voices[setting.voice];
  const first = [last, setting.name].filter(
    (name): name is string => typeof name === "string" && group.includes(name));
  return [...new Set([...first, ...group])];
}

/** The configured voices, the current one marked, and a note when the fleet is quiet. */
export function voiceList(setting: VoiceSetting, current: string | null, voices: Voices): string {
  const selected = current ?? setting.name ?? voices[setting.voice][0];
  const groups = KINDS.map((kind) => kind + ": "
    + voices[kind].map((voice) => voice + (voice === selected ? "*" : "")).join(", "));
  return "Voices - " + groups.join(" | ") + (setting.isOn ? "" : " | llm-fleet is quiet.");
}

/** How a voice introduces itself: `af_sky` says Sky. */
export function firstName(voice: string): string {
  const name = voice.includes("_") ? voice.slice(voice.indexOf("_") + 1) : voice;
  return name ? name[0]!.toUpperCase() + name.slice(1) : voice;
}

/** The reply once a voice has been tried: the one that spoke, or why none did. */
export function voiceReply(spoke: string | null, reason: string | null): string {
  if (spoke === null) {
    return "llm-fleet could not speak: " + (reason ?? "no configured voice answered") + ". "
      + SPEAK_USAGE;
  }
  return "llm-fleet speaks as " + spoke + " now.";
}

/** What `/speak` says when asked how things stand. */
export function speakStatus(setting: VoiceSetting, current: string | null,
                            info: SpeechInfo | null): string {
  if (info !== null && info.state !== "ready") {
    return "llm-fleet cannot speak: " + (info.reason ?? "speech is unavailable") + ". " + SPEAK_USAGE;
  }
  const voice = current ?? setting.name ?? setting.voice + " voice";
  return (setting.isOn ? "llm-fleet speaks as " + voice + ". "
    : "llm-fleet is quiet (" + setting.voice + " voice). ") + SPEAK_USAGE;
}

files.components/tab.ts:
/**
 * The terminal tab's color, by the band's level.
 *
 * A session whose band leads with a failure tints its terminal tab red, one
 * whose band leads with a wait tints it amber, and a band that clears gives the
 * tab its own color back, as the session ending does. The person sees which
 * tab needs them without looking at any of them.
 *
 * Only iTerm draws a tab color from an escape, and inside tmux only when tmux
 * passes escapes through to the terminal around it. Anywhere else nothing is
 * written at all: an escape another terminal does not know is drawn as noise
 * in the transcript, or swallowed, and neither is a tint.
 *
 * Several sessions can share one tab: tmux panes in one iTerm tab. The tab's
 * state is the helper's (`readers/tab.py`): it keeps one record per tab under
 * a lock, paints the highest level any live session holds, and writes the
 * escape to the session's terminal, since a plugin's own output is not the
 * terminal. What is here is this session's side, testable without a terminal:
 * the level from the band's items, the helper's words, and when to tell the
 * helper, which is when the level moves, once more after a paint that failed,
 * and every third of the staleness while a level is held.
 */

/** What the tab says: a failure, a wait, or nothing, which is the tab's own color. */
export type TabLevel = "failure" | "waiting" | null;

/** How the tab is tinted, as the configuration resolves it; the colors are the helper's to read. */
export type TabTint = { enabled: boolean; staleSeconds: number };

/** The schema's own defaults, for a reading that carries no tint of its own. */
export const TINT_DEFAULTS: TabTint = { enabled: true, staleSeconds: 120 };

/** The schema's floor for the staleness: the heartbeat at a third of it runs at most every ten seconds. */
export const STALE_FLOOR = 30;

/** The tint a reading carries, each part the default when it is not usable. */
export function tintFrom(value: unknown): TabTint {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return TINT_DEFAULTS;
  }
  const body = value as Record<string, unknown>;
  return {
    enabled: typeof body.enabled === "boolean" ? body.enabled : TINT_DEFAULTS.enabled,
    staleSeconds: typeof body.staleSeconds === "number" && Number.isInteger(body.staleSeconds)
      && body.staleSeconds >= STALE_FLOOR ? body.staleSeconds : TINT_DEFAULTS.staleSeconds,
  };
}

/**
 * The level the band's items put the tab at: a failure outranks a wait, and a
 * band with nothing in it is the tab's own color.
 */
export function tabLevel(items: readonly { level: "error" | "warning" }[]): TabLevel {
  if (items.some((item) => item.level === "error")) {
    return "failure";
  }
  return items.some((item) => item.level === "warning") ? "waiting" : null;
}

/** Where the session runs, as far as a tab color is concerned. */
export type TabTerminal = { supported: boolean; tmux: boolean };

/** What the environment says about the terminal, as the engine reads it. */
export type TabEnvironment = {
  termProgram?: string;
  lcTerminal?: string;
  tmux?: string;
};

/**
 * Whether this terminal draws a tab color, and whether the escape goes through tmux.
 *
 * iTerm names itself in `TERM_PROGRAM`; inside tmux that variable names tmux,
 * and `LC_TERMINAL`, which iTerm sets and tmux carries in, is what still says
 * iTerm. Inside tmux the escape reaches iTerm only when tmux passes it through
 * (`allow-passthrough`), so a tmux that does not is as unsupported as another
 * terminal.
 */
export function tabTerminal(env: TabEnvironment, passesThrough: boolean): TabTerminal {
  const iTerm = env.termProgram === "iTerm.app" || env.lcTerminal === "iTerm2";
  const tmux = typeof env.tmux === "string" && env.tmux !== "";
  return { supported: iTerm && (!tmux || passesThrough), tmux };
}

/** Whether tmux's answer to `show-options -gqv allow-passthrough` is a yes. */
export function passesThrough(answer: string): boolean {
  return ["on", "all"].includes(answer.trim());
}

/** The helper's word for a level. */
export function levelWord(level: TabLevel): "none" | "waiting" | "failed" {
  if (level === null) {
    return "none";
  }
  return level === "failure" ? "failed" : "waiting";
}

/**
 * The helper's words, what follows its path: this session's level for the tab,
 * or its end, with `--tmux` when the escape goes through tmux.
 */
export function tabArgs(form: "set" | "end", tab: string, session: string, level: TabLevel,
                        terminal: TabTerminal, recordOnly = false): string[] {
  const words = form === "end" ? ["end", "--tab", tab, "--session", session]
    : ["set", "--tab", tab, "--session", session, "--level", levelWord(level),
       ...(recordOnly ? ["--record-only"] : [])];
  return terminal.tmux ? [...words, "--tmux"] : words;
}

/**
 * What this session last told the helper: the level, when, how many times in a
 * row the helper said it could not paint it, and the run in flight, so one is
 * told at a time. The tab's own state is the helper's record, not this.
 */
export type TabSender = { sent: TabLevel | undefined; at: number; failures: number;
                          queue: Promise<void> };

/** A sender that has told the helper nothing. */
export function tabSender(): TabSender {
  return { sent: undefined, at: 0, failures: 0, queue: Promise.resolve() };
}

/**
 * Whether to tell the helper this level now: to paint, to keep the entry alive
 * without painting, or not at all.
 *
 * A new level is told at once. A held level is told again every third of the
 * staleness, so the entry never goes stale while the session holds it. With
 * `heartbeat`, which is tinting switched on, a session holding no level says
 * none as it starts and on the same beat: the helper prunes entries only when
 * some session speaks, so without it a failure whose session died would tint
 * the tab for good while the sessions left hold nothing. Once the helper could
 * not paint a level twice in a row the session gives up painting it until the
 * level moves, and the retelling then keeps the entry alive and paints nothing.
 */
export function nextSend(sender: TabSender, level: TabLevel, now: number,
                         staleSeconds: number, heartbeat = false): "paint" | "record" | null {
  if (sender.sent === undefined && level === null && !heartbeat) {
    return null;
  }
  if (level !== sender.sent) {
    return "paint";
  }
  if ((level !== null || heartbeat) && now - sender.at >= staleSeconds / 3) {
    return sender.failures >= 2 ? "record" : "paint";
  }
  return null;
}

/** Take in what telling the helper came to. A record-only run paints nothing, so it counts no failure. */
export function afterSend(sender: TabSender, level: TabLevel, now: number,
                          mode: "paint" | "record", landed: boolean): void {
  if (level !== sender.sent) {
    sender.failures = 0;
  }
  sender.sent = level;
  sender.at = now;
  if (mode === "paint") {
    sender.failures = landed ? 0 : sender.failures + 1;
  }
}

/**
 * Whether the session's end has anything to take back: an entry it holds, or a
 * clear the helper could not paint. A session that never held a level ends
 * without a word to the helper.
 */
export function endNeeded(sender: TabSender): boolean {
  return sender.sent !== undefined && (sender.sent !== null || sender.failures > 0);
}

/** Run one turn after whatever the sender is doing now, never two at once. */
export function serially(sender: TabSender, turn: () => Promise<void>): Promise<void> {
  const next = sender.queue.then(turn);
  sender.queue = next.catch(() => undefined);
  return sender.queue;
}

files.components/tips.ts:
/**
 * The key tip after the prompt hint, and the words `/keys` takes.
 *
 * While a draft is typed, the hint line under the prompt ends with one of the
 * tips the pane's Keys section lists, and the tip moves on at the interval the
 * configuration sets. The tips are the pane's own, so the line and the section
 * never disagree about what a key does.
 *
 * Whether tips show is two answers: the configuration's (`keys.tipsEnabled`),
 * and the person's own, set with `/keys tips off|on` and kept in the store so
 * it holds in the next session. Either one off is off, in the hint line and in
 * the Keys section alike.
 */

/** What `/keys` says when it is handed words it does not take. */
export const KEYS_USAGE = "Use /keys to open the llm-fleet pane on its keys, or /keys tips off|on.";

/** What `/keys` was asked: open the pane on Keys, switch the tips, or words it does not take. */
export type KeysRequest = "open" | { tips: boolean } | null;

/** Read `/keys`'s words. */
export function keysRequest(args: string): KeysRequest {
  const words = args.trim().split(/\s+/).filter((word) => word !== "");
  if (words.length === 0) {
    return "open";
  }
  if (words.length === 2 && words[0] === "tips" && (words[1] === "on" || words[1] === "off")) {
    return { tips: words[1] === "on" };
  }
  return null;
}

/**
 * Whether tips show: the configuration allows them and the person has not
 * turned them off. A preference never read, or not a yes or no, is no
 * preference, and the configuration decides.
 */
export function tipsShown(configured: boolean, preference: unknown): boolean {
  return configured && preference !== false;
}

/**
 * The tip at this turn of the rotation, or null when there is none to show.
 *
 * The turn counts up for the whole session, so a list that changed length
 * under it still lands on a tip rather than past the end.
 */
export function tipAt(tips: readonly string[], turn: number): string | null {
  if (tips.length === 0) {
    return null;
  }
  const index = ((Math.trunc(turn) % tips.length) + tips.length) % tips.length;
  return tips[index] ?? null;
}

/** The hint line's tail with a tip after whatever another hook put there. */
export function withTip(tail: string | undefined, tip: string): string {
  return (tail ?? "") + "  " + tip;
}

files.components/entries.ts:
/**
 * The Python scripts this plugin has, and the one way it starts them.
 *
 * Every script is named here and nowhere else, and every command that starts
 * one is built by `entryArgv`: the boundary check refuses a script name or a
 * Python interpreter in any other module the host loads, and the standalone
 * proof runs each entry below from a lone copy of the plugin folder, so a
 * script an install would not carry cannot be started without a test noticing.
 *
 * The pane starts the read command, the alerts helper and the tab helper. The
 * statusline entries are started by the statusline command line, not by the
 * pane; they are here because they are the plugin's to carry all the same.
 *
 * The table keeps one entry per line in this exact shape, because the
 * standalone proof reads it as written.
 */

/** The interpreter every entry runs under. */
export const PYTHON = "python3";

export const ENTRIES = {
  snapshot: "readers/snapshot.py",
  alerts: "readers/alerts.py",
  tab: "readers/tab.py",
  host: "readers/host.py",
  session: "readers/session.py",
  transcript: "readers/transcript.py",
  doctor: "readers/doctor.py",
  setup: "readers/setup.py",
  governance: "readers/governance.py",
  rates: "readers/rates.py",
  pacer: "readers/pacer.py",
} as const;

/** A key of the table, which is the only thing a caller names. */
export type Entry = keyof typeof ENTRIES;

/**
 * How an entry is started, as the person's plugin options set it.
 *
 * `python` is the interpreter, a name on the PATH or a full path; `configPath`
 * is the configuration file every entry reads, empty for the default place.
 */
export type Launch = { python: string; configPath: string };

/** The packaged launch: the interpreter on the PATH, and the default configuration. */
export const LAUNCH: Launch = { python: PYTHON, configPath: "" };

/** One option as a trimmed, non-empty string, or nothing. */
function optionText(value: unknown): string | null {
  if (typeof value !== "string") {
    return null;
  }
  const trimmed = value.trim();
  return trimmed.length ? trimmed : null;
}

/**
 * The launch the plugin's options declare, field by field.
 *
 * The host validates each option against the manifest before the module loads,
 * so a value of the wrong kind arrives only from a host that did not; it, and an
 * empty one, leave the packaged choice for that field.
 */
export function launchFrom(options: Readonly<Record<string, unknown>> | undefined): Launch {
  return {
    python: optionText(options?.python) ?? LAUNCH.python,
    configPath: optionText(options?.configPath) ?? LAUNCH.configPath,
  };
}

/** The command that starts an entry from the plugin root, with its arguments after it. */
export function entryArgv(root: string, entry: Entry, args: readonly string[] = [],
                          launch: Launch = LAUNCH): string[] {
  return [launch.python, `${root}/${ENTRIES[entry]}`, ...args];
}

/**
 * The variables an entry is started with: the configuration file the person
 * named, through the selector the loader reads, or none at all. The loader
 * refuses a relative path there by name, so a mistyped option is drawn as a
 * refused configuration rather than read from wherever the session started.
 */
export function entryEnv(launch: Launch): Record<string, string> | undefined {
  return launch.configPath ? { FLEET_CONFIG: launch.configPath } : undefined;
}

files.components/host.ts:
/**
 * The host elements this layout may use, declared as a narrow local subset.
 *
 * The engine ships a generated declaration describing its whole surface. This
 * file declares only the elements and the props this layout writes, so the
 * published tree carries a contract a person can read rather than a copy of
 * someone else's generated file. Packaging maps these declarations onto the
 * engine's own elements; the check in `make components-drift` fails when the
 * engine stops declaring a prop named here.
 *
 * Box owns flow, spacing and the right slot. Text owns titles, metadata, state
 * labels and the cells of the slim bar. Button owns the things a person can
 * press: a section that folds, the two that fold every section at once, and a
 * row title that copies what the row offers. Link owns a page a title names,
 * and Input owns the reply a waiting job is sent, where the surface draws one.
 *
 * Svg is the one element not every surface has: the desktop, the editor and the
 * phone draw it, and the terminal does not. The layout never asks for it. A bar,
 * a strip or a tile carries a drawing of itself beside its cells, and the mount
 * draws that instead of the cells where the surface's table holds an Svg, so the
 * same view model is a run of half-height glyphs in a terminal and a vector
 * shape on the desktop. Nothing here draws a raster: that is the terminal's alone.
 */

/** A color token, named by the theme rather than by a literal value. */
export type Color =
  | "text" | "subtle" | "inactive" | "success" | "error" | "warning"
  | "merged" | "claude" | "suggestion" | "planMode" | "promptBorder" | "bashBorder"
  /** The theme's soft red, the fill a removed line is drawn on: a failing row's shade. */
  | "diffRemovedDimmed"
  /** The theme's soft green, the fill an added line is drawn on: an arriving row's tint. */
  | "diffAddedDimmed"
  /** The text color drawn on a filled chip, which the theme keeps legible on any fill. */
  | "inverseText";

/**
 * What a box changes while the pointer is over it.
 *
 * The surface applies these itself, with no hook run and nothing crossing to
 * the plugin, so a card that brightens or a hint that shows on hover costs the
 * pane no paint. None of them moves a sibling except `display`, which is how a
 * line hidden at rest is shown.
 */
export type BoxHoverProps = {
  borderColor?: Color;
  borderDimColor?: boolean;
  backgroundColor?: Color;
  display?: "flex";
};

/** What a text changes while the pointer is over the keyed box around it. */
export type TextHoverProps = {
  color?: Color;
  backgroundColor?: Color;
  dimColor?: boolean;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  inverse?: boolean;
};

export type BoxProps = {
  /**
   * The box's address, which makes it a hover scope: while the pointer is over
   * it, its own `hover` and that of everything beneath it apply.
   */
  key?: string;
  /** What the surface draws differently while the pointer is over this box. */
  hover?: BoxHoverProps;
  /** `none` draws nothing at rest, which a hover may turn back to `flex`. */
  display?: "flex" | "none";
  /**
   * How the box is placed among its siblings.
   *
   * `absolute` takes it out of the flow and places it against its parent, which
   * is what lets a hidden box be revealed over the content rather than beside
   * it: nothing moves when it appears, and it costs no room while it is hidden.
   */
  position?: "relative" | "absolute";
  /** Where an absolute box sits against its parent: cells right and down. */
  top?: number;
  left?: number;
  /** The direction children flow in. A column is the default reading order. */
  flexDirection?: "row" | "column";
  /** Space between children, or between them along one axis only. */
  gap?: number;
  rowGap?: number;
  columnGap?: number;
  /** A fixed width, or the minimum width this box will take. */
  width?: number;
  minWidth?: number;
  /** How this box shares spare width with its siblings. */
  flexGrow?: number;
  flexShrink?: number;
  /** How children are placed along the flow axis and across it. */
  justifyContent?: "flex-start" | "flex-end" | "center" | "space-between";
  alignItems?: "flex-start" | "flex-end" | "center";
  /** Space inside the box, in cells. */
  paddingX?: number;
  paddingY?: number;
  /** Space outside it, which is what separates one card from the next. */
  marginTop?: number;
  marginBottom?: number;
  marginX?: number;
  marginLeft?: number;
  marginRight?: number;
  /**
   * The box's rule, drawn by the surface.
   *
   * A card is a bordered box, which is what makes a run of sections read as
   * tiles rather than as a list of headings: the drawing is the surface's, so
   * the same tree is a boxed card on the desktop and a boxed card in a
   * terminal.
   */
  borderStyle?: "round" | "single" | "bold" | "double";
  borderColor?: Color;
  borderDimColor?: boolean;
  /** Fills the box, which is how a bar or a pressed control reads as a block. */
  backgroundColor?: Color;
};

export type TextProps = {
  /** A declared token, never a raw value. */
  color?: Color;
  /** Fills the cells this text occupies, which is how a bar is drawn solid. */
  backgroundColor?: Color;
  /** For idle and historical metadata: quieter than any token. */
  dimColor?: boolean;
  bold?: boolean;
  /** For what a row says in its own words, such as the question it waits on. */
  italic?: boolean;
  /** What the surface draws differently while the pointer is over the box around it. */
  hover?: TextHoverProps;
  /** How a value too long for its line is continued. */
  wrap?: "wrap" | "truncate-end" | "truncate-start" | "truncate-middle";
};

/**
 * The one element a person can act on.
 *
 * `key` is the element's address: it is what `ui.press` carries as `e.element`,
 * and what the entry matches on to know which section was folded. `hotkey` is
 * one digit or one lowercase letter, pressed while the pane holds the focus,
 * which is why the layout gives each button a different one.
 */
export type ButtonProps = {
  /** The element's address, and what a press handler matches on. */
  key: string;
  /** What the button draws; a section's heading, or "Collapse all". */
  label: string;
  /**
   * What a press does. The host runs this in the plugin's own environment, so
   * it is how the pane hears about a press at all: a button drawn without one
   * is refused rather than drawn inert, which is why this is required here as
   * it is required by the engine.
   */
  onPress: () => void;
  /** One digit or one lowercase letter that presses it. */
  hotkey?: string;
  /**
   * Drawn quieter than the text around it.
   *
   * The engine's button carries no `bold` and no `color`: its weight and its
   * color are the surface's, and a layout that named one would drift.
   */
  dimColor?: boolean;
  /**
   * Drawn without the bracket chrome: the hotkey in the accent color, a colon,
   * then the label, which is how the host's own shortcut rows read.
   */
  plain?: true;
  /**
   * Which of several buttons is the main action: a primary one is drawn in the
   * accent color, as the surface marks the one to press.
   */
  variant?: "primary" | "secondary";
  /**
   * The label's look while the pointer is over the keyed box around it: a row
   * title that copies something lights as the host lights a row under its cursor.
   */
  hover?: TextHoverProps;
};

/**
 * A hyperlink: an OSC 8 span on the terminal, an anchor on the desktop.
 *
 * Inline, like a text: its children are what it reads as. What a click opens is
 * the surface's, so a pull request's title is a link to its page and the pane
 * runs nothing for it.
 */
export type LinkProps = {
  /** Where it goes, as written. */
  href: string;
  /** What it reads as when it holds no children. */
  label?: string;
};

/**
 * A text field, on the surfaces that draw one: the terminal, the desktop and
 * the editor. The phone draws none, so the layout asks for a field only where
 * the mount bound one, and offers a press instead everywhere else.
 */
export type InputProps = {
  /** The field's address, which a test types into and a matcher names. */
  key: string;
  /** Drawn before the field. */
  label?: string;
  /** Drawn dim while the field is empty. */
  placeholder?: string;
  /** What Enter does, drawn beside the field while it has the focus. */
  submitLabel?: string;
  /** What Enter does, run by the host in the plugin's own environment. */
  onSubmit: (value: string) => void;
};

/**
 * The props of the remote surfaces' vector leaf.
 *
 * The markup is the element's data and is drawn isolated, as an image: no theme
 * key reaches it, so the drawing carries its own colors. `alt` is required by
 * the engine, and it is what a surface without the element, or a reader that
 * cannot see it, gets instead.
 */
export type SvgProps = {
  /** The SVG document, at most 131072 characters. */
  source: string;
  /** What the drawing says, in words. */
  alt: string;
  /** CSS pixels; absent, the markup's own width up to the slot. */
  width?: number;
  /** CSS pixels; absent, the markup's own height at the drawn width. */
  height?: number;
};

/**
 * A drawing of a node, for a surface that draws vectors.
 *
 * `cells` is how many cells the node takes on a terminal, which is the slot the
 * drawing is given on the desktop: the same view model lays out the same way on
 * both, and only what fills the slot differs.
 */
export type Vector = {
  source: string;
  alt: string;
  cells: number;
};

/** A node of the rendered tree, as a host would build it. */
export type Node = {
  type: "Box" | "Text" | "Button" | "Svg" | "Link" | "Input";
  props: BoxProps | TextProps | SvgProps | LinkProps | InputProps
    | (ButtonProps & { children?: (Node | string)[] });
  children: (Node | string)[];
  /**
   * The node drawn as a vector, for a surface that has one. Never a prop: the
   * mount reads it and hands the surface either this or the node, not both.
   */
  vector?: Vector;
};

/**
 * The host's element constructors, narrowed to the subset above.
 *
 * A local declaration is a subset of the host's props, so the host's own
 * constructor is assignable to this type without a cast; only the boundary that
 * receives the resolved elements needs one, and that boundary is where the
 * drift check applies.
 */
export type ElementConstructor<P> = (props: P) => Node;

export type Primitives = {
  Box: ElementConstructor<BoxProps & { children?: (Node | string)[] }>;
  Text: ElementConstructor<TextProps & { children?: (Node | string)[] }>;
  Button: ElementConstructor<ButtonProps & { children?: (Node | string)[] }>;
  /** Present only where the surface draws vectors: never on the terminal. */
  Svg?: ElementConstructor<SvgProps>;
  /** Every surface draws a link; absent from a recording that asked for none. */
  Link?: ElementConstructor<LinkProps & { children?: (Node | string)[] }>;
  /** Present only where the surface draws a text field: never on the phone. */
  Input?: ElementConstructor<InputProps>;
};

/** A layout tree, built without a host, so a test can read its structure. */
export type Tree = Node;

files.components/vector.ts:
/**
 * The pane's shapes as vectors: a bar, a strip of hours, a tile.
 *
 * A terminal draws these out of half-height glyphs in theme colors, and that is
 * the right drawing there. A desktop draws text in its own fonts, where a run of
 * block characters is a dotted line rather than a bar, so a surface that draws
 * vectors gets the same shape as markup instead. Each function here takes what
 * the cell drawing was built from, never the cells themselves, so the two
 * drawings cannot say different things.
 *
 * The markup is drawn isolated, as an image, and no theme key reaches it. The
 * colors are written in, a pair per token, one for a light page and one for a
 * dark one, picked by the page's color scheme. They are chosen to read on either
 * page, not copied from the host's themes, so a person's own theme colors the
 * text around a bar and not the bar.
 *
 * Every drawing is sized in cells the way the terminal lays it out, at a cell
 * wider than any code font draws one, so the surface scales it down to the slot
 * the layout gave it rather than leaving it short of that slot.
 */

import type { Color, Vector } from "./host.ts";

/** Pixels a cell is drawn at in the markup: wider than a code font's advance. */
export const CELL_PIXELS = 10;

/** A bar's height in the markup, and the stroke of its track inside that. */
const BAR_HEIGHT = 8;
const BAR_STROKE = 5;

/** A strip block's height in the markup: taller than a bar, as a strip is read block by block. */
const STRIP_HEIGHT = 12;

/**
 * A tile's height in the markup: the four rows a bordered tile takes. Its text is
 * set larger than the page's because the surface scales the drawing down by the
 * ratio of a code font's cell to this file's, about four fifths.
 */
const TILE_HEIGHT = 62;

/** The light and dark color for each token a drawing can be asked for. */
const PALETTE: Record<Color, [string, string]> = {
  text: ["#1f1f1f", "#ececec"],
  inverseText: ["#ffffff", "#1f1f1f"],
  subtle: ["#8a8a8a", "#8a8a8a"],
  inactive: ["#8a8a8a", "#9a9a9a"],
  success: ["#2c7a39", "#4eba65"],
  error: ["#ab2b3f", "#ff6b80"],
  warning: ["#966c1e", "#ffc107"],
  merged: ["#8700ff", "#af87ff"],
  claude: ["#c2643f", "#d77757"],
  suggestion: ["#5769f7", "#b1b9f9"],
  planMode: ["#006666", "#48968c"],
  promptBorder: ["#999999", "#888888"],
  bashBorder: ["#d6006f", "#fd5db1"],
  diffRemovedDimmed: ["#fbd5da", "#4a2a2e"],
  diffAddedDimmed: ["#cfe8d3", "#2b4330"],
};

/** The dark page's half of a drawing's style, which starts here. */
const DARK_SCHEME = "@media (prefers-color-scheme: dark){";

/** The class a token's fill is drawn with. */
function fillClass(color: Color): string {
  return "f-" + color;
}

/**
 * The style block for the tokens one drawing uses, and the track and rule every
 * drawing may use: written per drawing so the markup carries only what it draws.
 */
function style(colors: Color[]): string {
  const used = [...new Set(colors)];
  const light = used.map((color) => `.${fillClass(color)}{fill:${PALETTE[color][0]}}`).join("");
  const dark = used.map((color) => `.${fillClass(color)}{fill:${PALETTE[color][1]}}`).join("");
  return "<style>"
    + light
    + ".track{fill:#000000;fill-opacity:.1}"
    + ".rule{fill:#000000;fill-opacity:.03;stroke:#000000;stroke-opacity:.18}"
    + ".muted{fill:#6b6b6b}"
    + DARK_SCHEME
    + dark
    + ".track{fill:#ffffff;fill-opacity:.16}"
    + ".rule{fill:#ffffff;fill-opacity:.04;stroke:#ffffff;stroke-opacity:.2}"
    + ".muted{fill:#a0a0a0}"
    + "}</style>";
}

/**
 * A drawing's markup with each token's fill written as another token's.
 *
 * Only the style block `style` wrote is touched: each `.f-<token>{fill:...}` rule
 * takes the light fill of the token `swap` names before the dark-scheme block,
 * and its dark fill inside it. The classes on the shapes stay as they were, so
 * the drawing keeps saying which state each shape is; only how it looks moves.
 *
 * A tile's outline is the `.rule` stroke, a neutral the terminal draws in the
 * quiet token: when the theme moves that token, the outline is drawn in the
 * token it moved to, so a tile's border on the desktop follows the terminal's.
 */
export function restyle(source: string, swap: (token: Color) => Color): string {
  const fill = (scheme: 0 | 1) => (rule: string, token: string): string => {
    if (!(token in PALETTE)) {
      return rule;
    }
    return `.${fillClass(token as Color)}{fill:${PALETTE[swap(token as Color)][scheme]}}`;
  };
  const quiet = swap("subtle");
  const outline = (scheme: 0 | 1) => (rule: string, before: string): string =>
    quiet === "subtle" ? rule : `.rule{${before}stroke:${PALETTE[quiet][scheme]};stroke-opacity:1}`;
  const fills = /\.f-([A-Za-z]+)\{fill:#[0-9a-fA-F]{3,8}\}/g;
  const outlines = /\.rule\{([^}]*?)stroke:#[0-9a-fA-F]{3,8};stroke-opacity:[.0-9]+\}/g;
  const scheme = (part: string, which: 0 | 1): string =>
    part.replace(fills, fill(which)).replace(outlines, outline(which));
  const split = source.indexOf(DARK_SCHEME);
  if (split === -1) {
    return scheme(source, 0);
  }
  return scheme(source.slice(0, split), 0) + scheme(source.slice(split), 1);
}

/** Text placed in markup, so a title holding `<` or `&` is drawn rather than parsed. */
export function escapeXml(value: string): string {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}

/** The document around a drawing, at its own size in markup pixels. */
function svg(width: number, height: number, colors: Color[], body: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" `
    + `viewBox="0 0 ${width} ${height}">${style(colors)}${body}</svg>`;
}

/** A number as markup writes it: no float noise a reader of the source trips on. */
function px(value: number): string {
  return String(Math.round(value * 100) / 100);
}

/**
 * A rate bar: the track across the slot and the done share filled over it.
 *
 * The share is the exact proportion, not the cells the terminal rounds it to:
 * a vector has no cell to round to. The callers have already refused a bar with
 * no denominator or with impossible counts, and so does this, by returning
 * nothing, because a drawing of one is the claim those refusals exist to stop.
 */
export function barVector(done: number, total: number, color: Color, cells: number): Vector | null {
  if (!(total > 0) || !Number.isFinite(done) || !Number.isFinite(total)
      || done < 0 || done > total || cells < 1) {
    return null;
  }
  const width = cells * CELL_PIXELS;
  const top = (BAR_HEIGHT - BAR_STROKE) / 2;
  const radius = BAR_STROKE / 2;
  const filled = width * (done / total);
  const track = `<rect class="track" x="0" y="${px(top)}" width="${width}" `
    + `height="${BAR_STROKE}" rx="${px(radius)}"/>`;
  const fill = filled > 0
    ? `<rect class="${fillClass(color)}" x="0" y="${px(top)}" width="${px(filled)}" `
      + `height="${BAR_STROKE}" rx="${px(radius)}"/>`
    : "";
  return {
    source: svg(width, BAR_HEIGHT, [color], track + fill),
    alt: `${done} of ${total}`,
    cells,
  };
}

/** One bucket of a strip: how many things landed in it and how many failed. */
export type StripCell = { outcomes: number; failed: number };

/**
 * A strip of the recent past, one rounded block per bucket, oldest first.
 *
 * A bucket nobody tried anything in is track, one that held a failure is the
 * error color, and the rest are the success color: the same alphabet the
 * terminal strip uses, for the same reason, that an empty hour is not a good one.
 */
export function stripVector(cells: StripCell[], alt: string): Vector | null {
  if (!cells.length) {
    return null;
  }
  const width = cells.length * CELL_PIXELS;
  const gap = 2;
  const used: Color[] = [];
  const blocks = cells.map((cell, index) => {
    const tone: Color | null = cell.outcomes === 0 ? null : cell.failed > 0 ? "error" : "success";
    if (tone) {
      used.push(tone);
    }
    return `<rect class="${tone ? fillClass(tone) : "track"}" x="${index * CELL_PIXELS}" y="0" `
      + `width="${CELL_PIXELS - gap}" height="${STRIP_HEIGHT}" rx="2"/>`;
  }).join("");
  return { source: svg(width, STRIP_HEIGHT, used, blocks), alt, cells: cells.length };
}

/** The inset of a tile's words from its edges, in markup pixels. */
const TILE_INSET = 12;

/**
 * The widest a character of a tile's label and of its value is drawn, in markup
 * pixels: a sans face's widest common glyphs at 14 px and at 19 px semibold. Cut
 * by this, a word never reaches the card's edge, where the drawing would clip
 * its end and the truncation mark with it.
 */
const LABEL_CHAR_PIXELS = 8.5;
const VALUE_CHAR_PIXELS = 12;

/** The mark a cut word ends with, as the layout writes it. */
const CUT = "...";

/** A word cut to a number of characters, the cut marked so a reader knows. */
export function cutTo(value: string, chars: number): string {
  if (value.length <= chars) {
    return value;
  }
  if (chars <= CUT.length) {
    return value.slice(0, Math.max(0, chars));
  }
  return value.slice(0, chars - CUT.length) + CUT;
}

/**
 * A tile: a rounded card holding a figure's label and its value.
 *
 * The words come in whole and are cut here by the room they take in the
 * drawing, which is not the room they take in cells: a figure set large in a
 * proportional face is wider than the same figure in a code font. The alt says
 * both whole, since it has no width to keep to.
 */
export function tileVector(label: string, value: string, color: Color, cells: number): Vector {
  const width = Math.max(1, cells) * CELL_PIXELS;
  const room = Math.max(0, width - 2 * TILE_INSET);
  const font = "font-family=\"ui-sans-serif,system-ui,-apple-system,sans-serif\"";
  const shownLabel = cutTo(label, Math.floor(room / LABEL_CHAR_PIXELS));
  const shownValue = cutTo(value, Math.floor(room / VALUE_CHAR_PIXELS));
  const body = `<rect class="rule" x="0.5" y="0.5" width="${width - 1}" `
    + `height="${TILE_HEIGHT - 1}" rx="7"/>`
    + `<text class="muted" x="${TILE_INSET}" y="25" font-size="14" ${font}>`
    + `${escapeXml(shownLabel)}</text>`
    + `<text class="${fillClass(color)}" x="${TILE_INSET}" y="49" font-size="19" font-weight="600" `
    + `${font}>${escapeXml(shownValue)}</text>`;
  return { source: svg(width, TILE_HEIGHT, [color], body), alt: `${label}: ${value}`, cells };
}

files.components/version.ts:
/**
 * The version the pane names in its footer.
 *
 * Generated from plugins/llm-fleet/.claude-plugin/plugin.json by
 * scripts/version.py. Do not edit this file: change the manifest and run
 * `make version`.
 */
export const PLUGIN_VERSION = "0.4.16";

/** What the footer says: the plugin, who writes it, and the license. */
export const FOOTER_TEXT = "llm-fleet " + PLUGIN_VERSION + " \u00b7 Doric Stack LLC \u00b7 MIT";

files.components/cards.ts:
/**
 * The pieces a tile is built from: a stat card, a status dot, a rate bar.
 *
 * These are drawn with the surface's own elements rather than assembled out of
 * characters. A card is a bordered box and a bar is a run of filled cells in a
 * theme color. A bar and a strip also carry a vector drawing of themselves, built
 * from the same counts, which the mount draws instead of the cells on a surface
 * that draws vectors; neither this file nor the layout it serves has to know
 * which surface is drawing it.
 *
 * The border characters are written as code points because this repository's
 * source is plain ASCII: a literal box-drawing character in a source file is
 * what the format rule refuses, and naming it is what the rule asks for instead.
 */

import type { Color, Node } from "./host.ts";
// Type-only, so the cycle with layout.ts is erased rather than evaluated: the
// layout draws with the pieces here, so the pieces cannot draw with it.
import type { History, PaneCard, Slot } from "./layout.ts";
import { box, fit, pressable, text } from "./layout.ts";
import { barVector, stripVector } from "./vector.ts";

/**
 * The mark a bar is drawn with, filled and track alike: a heavy line on the
 * middle of the cell. A full block read as a slab beside the text and a light
 * line as a rule; the half block sat on the cell's floor, so a bar touched the
 * row under it and read as that row's underline. The filled part is told from
 * the track by its color, and the track is the same mark drawn dim.
 */
export const BAR_FILLED = "\u2501";
export const BAR_TRACK = "\u2501";

/**
 * The mark a heading or a state is drawn behind: a thin bar of its color at the
 * left of the word, where a chip put the whole word on a block of it. A section
 * of chips was a column of yellow and green slabs louder than the counts beside
 * them.
 */
export const ACCENT = "\u258e";

/** The dot that says what an item is doing, without a word for it. */
export const DOT_FILLED = "●";

/** The mark a folded section's heading carries. */
export const FOLDED = "▸";
/** The mark an open section's heading carries. */
export const OPENED = "▾";

/**
 * What a state is drawn as: one color per meaning, never a literal.
 *
 * A state the pane does not recognize draws as the quiet token rather than as a
 * success: an unread state is not good news, and a dot that went green for a
 * word nobody knows would be the pane inventing a verdict.
 */
export function stateColor(state: string): Color {
  switch (state) {
    case "working":
    case "running":
    case "ready":
    case "active":
    case "passed":
    case "green":
      return "success";
    case "waiting":
    case "blocked":
    case "stale":
    case "pending":
    case "draft":
    case "expired":
    case "held":
    case "unknown":
      return "warning";
    case "failed":
    case "error":
      return "error";
    case "merged":
    case "preserved":
      return "merged";
    default:
      return "subtle";
  }
}

/** The dot for a state, drawn in that state's own color. */
export function statusDot(state: string): Node {
  return text({ color: stateColor(state) }, DOT_FILLED);
}

/**
 * A word on a fill of its own color: the mark a live state and a headline
 * figure are drawn with, as the host draws a working session's name.
 *
 * The fill repeats a word that is already there, so nothing is carried by the
 * color alone; the text on it is the theme's own inverse, which the theme keeps
 * legible on every fill it defines.
 */
export function chip(value: string, color: Color): Node {
  // The cell of fill at each side is its own text, so the word is the word: a
  // reader of the tree, or a search of what the pane says, finds "Waiting" and
  // not the padding it is drawn with.
  const fill = { backgroundColor: color, color: "inverseText" as const };
  return box({ flexDirection: "row", gap: 0, flexShrink: 0 }, [
    text(fill, " "), text({ ...fill, bold: true }, value), text(fill, " "),
  ]);
}

/**
 * A word in its color behind the accent, on no fill: the mark a heading and a
 * state are drawn with. It takes the width a chip took, so nothing beside it
 * moves; the chip is kept for the short figures, where a block is one cell or two.
 */
export function tag(value: string, color: Color): Node {
  return box({ flexDirection: "row", gap: 0, flexShrink: 0 }, tagTexts(value, color));
}

/** A tag's texts alone, for a control or a link, which may hold texts and no box. */
export function tagTexts(value: string, color: Color): Node[] {
  return [text({ color }, ACCENT), text({}, " "), text({ color, bold: true }, value)];
}

/**
 * The states drawn as a chip on a row's title: work that is live, or waiting on
 * a person, or broken. A finished or merged item keeps a plain title, because a
 * list of finished things each on a fill is a list where nothing stands out.
 */
// Only the states that need a person, or that failed: a fill on every live item
// is a section of green bars where the one that needs you does not stand out.
const CHIP_STATES = new Set(["waiting", "blocked",
                             "failed", "error"]);

/** The fill a row's title is drawn on, or none for a state that earns no chip. */
export function titleChip(state: string): Color | null {
  return CHIP_STATES.has(state) ? stateColor(state) : null;
}

/** One figure: its value on a chip in its own color, and the word for it. */
function statCell(card: PaneCard, each: number): Node {
  const cell = box({ flexDirection: "row", gap: 1 }, [
    chip(fit(card.value, 6), card.color ?? "subtle"),
    text({ dimColor: true }, fit(card.label, Math.max(4, each - card.value.length - 3))),
  ]);
  // A figure that is a way into what it counts is drawn as the control it is:
  // the whole cell is the press, so a person presses the number they read.
  // A press holds words and Text only: the host refuses any other child and
  // the whole pane with it, so the cell's box is unwrapped into what it says.
  return card.press
    ? { type: "Button", props: { key: card.press.key,
                                 // The figure's own words carry its number: a
                                 // reader of the tree finds "4 Working sessions",
                                 // and a review page that prints the label alone
                                 // still shows the figure a change moved.
                                 label: card.value + " " + card.press.label,
                                 onPress: card.press.onPress },
        children: pressable([cell]) }
    : cell;
}

/** The least a label keeps when the figures share one line. */
const STATS_LABEL_FLOOR = 8;

/**
 * The width each figure takes on one line, or null when they must stack.
 *
 * A figure's label is the word that makes its number mean something, so the
 * cards are sized to their own labels rather than to an equal share. A share
 * chosen for the longest label leaves the short ones' room unread; a share
 * chosen for the shortest cuts the long one, and "Failed trials..." is the
 * label the pane exists to state.
 *
 * The spare width goes to the card furthest from whole, one cell at a time, so
 * every label is cut by about the same amount rather than the longest by all of
 * it.
 */
function shareWidths(cards: { label: string; value: string }[], width: number): number[] | null {
  const gaps = 3 * Math.max(0, cards.length - 1);
  const needed = cards.map((card) => card.value.length + 2 + 1 + card.label.length);
  const least = cards.map((card) => card.value.length + 2 + 1 + STATS_LABEL_FLOOR);
  const floor = least.reduce((sum, cells) => sum + cells, 0) + gaps;
  if (cards.length === 0 || width < floor) {
    return null;
  }
  const sizes = [...least];
  let spare = width - floor;
  while (spare > 0) {
    let pick = -1;
    for (const [index, size] of sizes.entries()) {
      if (size >= needed[index]) {
        continue;
      }
      if (pick < 0 || needed[index] - size > needed[pick] - sizes[pick]) {
        pick = index;
      }
    }
    if (pick < 0) {
      break;
    }
    sizes[pick] += 1;
    spare -= 1;
  }
  return sizes;
}

/**
 * The head of a pane: every headline figure on one line, each on its chip.
 *
 * They are drawn as one line rather than as a card each, and with no rule round
 * them: three cards holding a single digit divide the pane into three empty
 * boxes, and a rule round one line spends two rows the sections below need. The
 * chip is what makes a figure read first; the label beside it names what it
 * counts, written rather than cut, because "Failed trials and runs" is the label
 * and "Failed tri..." is the thing this replaced.
 *
 * Too narrow for three side by side, the figures stack rather than shrinking to
 * initials: a pane a third of the width it wants still has figures worth reading.
 */
export function statStrip(cards: PaneCard[], width: number, measured = false): Node {
  // A caller that measured the figures against its own line already knows they
  // fit there whole, so each label keeps its full length rather than a share.
  if (measured) {
    return box({ flexDirection: "row", gap: 3 },
               cards.map((card) => statCell(card, card.label.length + 10)));
  }
  const sizes = shareWidths(cards, width);
  if (sizes === null) {
    return box({ flexDirection: "column", gap: 0 },
               cards.map((card) => statCell(card, width)));
  }
  return box({ flexDirection: "row", gap: 3 },
             cards.map((card, index) => statCell(card, sizes[index])));
}

/**
 * A stretch of the recent past, one cell per bucket, oldest first.
 *
 * The cells are the bar's own alphabet: a bucket that held nothing failed is
 * filled, one that held a failure is filled in the error color, and one nobody
 * tried anything in is left as track. That last one is why this is not a bar: an
 * empty bucket drawn as filled would say the hour went well, and the pane has no
 * basis for that. The caption states what the buckets add up to, because twelve
 * cells cannot say how many trials they are.
 */
export function historyStrip(history: History, width: number): Node | null {
  if (!history.cells.length || history.outcomes <= 0) {
    return null;
  }
  const room = Math.max(1, width);
  // One cell per bucket, oldest first. Too narrow for all of them, the oldest
  // are dropped and the caption says which stretch is left: a strip of eight
  // cells under the words "Last 12 hours" is a label claiming hours it is not
  // showing, and the cells a reader counts would not be the ones they think.
  const shown = history.cells.slice(-room);
  const dropped = history.cells.length - shown.length;
  const drawn = box({ flexDirection: "row", gap: 0 },
                    shown.map((cell) => text(
                      cell.outcomes === 0 ? { dimColor: true }
                        : { color: cell.failed > 0 ? "error" : "success" },
                      cell.outcomes === 0 ? BAR_TRACK : BAR_FILLED)));
  const caption: Slot[] = [
    { text: dropped > 0 ? "Last " + shown.length + " hours" : history.label, dim: true },
    { text: " " + history.outcomes + (history.outcomes === 1 ? " outcome" : " outcomes") },
  ];
  if (history.failed > 0) {
    caption.push({ text: "  " + history.failed + " failed", color: "error" });
  }
  // The vector says in its alt what the caption says, since a reader of the
  // drawing alone has no caption.
  const vector = stripVector(shown, caption.map((slot) => slot.text.trim()).join(", "));
  return box({ flexDirection: "column", gap: 0 },
             [vector ? { ...drawn, vector } : drawn, stripLine(caption)]);
}

/** The caption under a strip, laid out as one line of text. */
function stripLine(slots: Slot[]): Node {
  return box({ flexDirection: "row", gap: 0 },
             slots.map((slot, index) => text(
               { ...(slot.color ? { color: slot.color } : {}),
                 ...(slot.dim ? { dimColor: true } : {}) },
               index === 0 || slot.text.startsWith(" ") ? slot.text : " " + slot.text)));
}

/** The small dot a check run is drawn as, one per check, side by side. */
export const CHECK_DOT = "•";

/** A check run's color: passed, failed and pending in their own, anything else quiet. */
export function checkColor(state: string): Color {
  switch (state) {
    case "pass":
      return "success";
    case "fail":
      return "error";
    case "pending":
      return "warning";
    default:
      return "subtle";
  }
}

/** How bad a check is, so a cap keeps the worst: failing, then pending, then the rest. */
function checkSeverity(state: string): number {
  return state === "fail" ? 2 : state === "pending" ? 1 : 0;
}

/**
 * A pull request's checks as a run of dots, one per check in its own color, and
 * the count of those not drawn.
 *
 * Too many for the room, the failing checks are kept first and then the pending
 * ones, in the order they were listed, and what was left out joins the count the
 * reader already left out, so every check is either a dot or a figure. Null when
 * there is nothing to draw or not even the count fits.
 */
export function checkDots(states: string[], more: number,
                          room: number): { node: Node; width: number } | null {
  const counted = (left: number): string => left > 0 ? " +" + left : "";
  let kept = states.length;
  while (kept > 0 && kept + counted(states.length - kept + more).length > room) {
    kept -= 1;
  }
  const tail = counted(states.length - kept + more);
  // The count's leading space parts it from a dot; with no dot it has nothing to part from.
  const width = kept ? kept + tail.length : tail.trimStart().length;
  if (width === 0 || width > room) {
    return null;
  }
  const order = states.map((state, index) => ({ state, index }))
    .sort((left, right) => checkSeverity(right.state) - checkSeverity(left.state)
                           || left.index - right.index)
    .slice(0, kept)
    .sort((left, right) => left.index - right.index);
  const parts = order.map((entry) => text({ color: checkColor(entry.state) }, CHECK_DOT));
  if (tail) {
    parts.push(text({ dimColor: true }, tail.trimStart()));
  }
  // The count is its own text, a cell from the last dot, so it reads as a figure.
  const node = box({ flexDirection: "row", gap: 0 }, tail && kept
    ? [...parts.slice(0, -1), text({}, " "), parts.at(-1) as Node] : parts);
  return { node, width };
}

/** The eight heights a spend bucket is drawn at, lowest first. */
export const SPARK_GLYPHS = ["▁", "▂", "▃", "▄",
                             "▅", "▆", "▇", "█"];

/**
 * A series as one line of block glyphs, each scaled to the busiest cell.
 *
 * Too long for the room, neighboring buckets are summed so the whole window is
 * still drawn, grouped from the newest end so the last cell ends at the reading.
 * A cell that held nothing is the lowest glyph drawn quiet, so it is not read as
 * the least spend; any spend at all is at least the lowest glyph in color. The
 * scale is the busiest cell and nothing else: no budget is drawn against.
 */
export function sparkline(values: number[], room: number, color: Color = "suggestion"): Node | null {
  const cells = Math.floor(room);
  if (!values.length || cells < 1) {
    return null;
  }
  const size = Math.ceil(values.length / cells);
  const sums: number[] = [];
  for (let end = values.length; end > 0; end -= size) {
    sums.unshift(values.slice(Math.max(0, end - size), end).reduce((sum, value) => sum + value, 0));
  }
  const peak = Math.max(...sums);
  return box({ flexDirection: "row", gap: 0 }, sums.map((sum) => {
    if (!(sum > 0) || !(peak > 0)) {
      return text({ dimColor: true }, SPARK_GLYPHS[0] as string);
    }
    const level = Math.min(SPARK_GLYPHS.length, Math.max(1, Math.ceil((sum / peak) * SPARK_GLYPHS.length)));
    return text({ color }, SPARK_GLYPHS[level - 1] as string);
  }));
}

/** The marks a timeline is drawn with: work and waiting heavy, idle light, unknown dashed. */
export const TIMELINE_HEAVY = "━";
export const TIMELINE_LIGHT = "─";
export const TIMELINE_UNKNOWN = "┄";

/** A stretch of a session's time, in seconds, and what it was doing. */
export type Stretch = { start: number; end: number; state: string };

/** What each state is drawn as on a timeline. */
function stretchLook(state: string | null): { glyph: string; props: { color?: Color; dimColor?: boolean } } {
  switch (state) {
    case "working":
      return { glyph: TIMELINE_HEAVY, props: { color: "success" } };
    case "waiting":
      return { glyph: TIMELINE_HEAVY, props: { color: "warning" } };
    case "idle":
      return { glyph: TIMELINE_LIGHT, props: { color: "subtle" } };
    default:
      return { glyph: TIMELINE_UNKNOWN, props: { dimColor: true } };
  }
}

/** Which state wins a cell two stretches share equally: the one that needs a person, then work. */
const STRETCH_RANK: Record<string, number> = { waiting: 3, working: 2, idle: 1 };

/**
 * A session's time from `from` to `to` as one line of cells, each in the state
 * that covered most of it.
 *
 * Time no stretch covers is drawn as unknown rather than as idle: a session
 * nothing was recorded for may have been doing anything. Null when the span is
 * empty or there is no room.
 */
export function timelineStrip(stretches: Stretch[], from: number, to: number, room: number,
                              dim = false): Node | null {
  const cells = Math.floor(room);
  if (cells < 1 || !(to > from) || !stretches.length) {
    return null;
  }
  const step = (to - from) / cells;
  const parts: Node[] = [];
  for (let cell = 0; cell < cells; cell += 1) {
    const left = from + cell * step;
    const right = left + step;
    const covered: Record<string, number> = {};
    for (const stretch of stretches) {
      const overlap = Math.min(right, stretch.end) - Math.max(left, stretch.start);
      if (overlap > 0) {
        covered[stretch.state] = (covered[stretch.state] ?? 0) + overlap;
      }
    }
    const unknown = step - Object.values(covered).reduce((sum, value) => sum + value, 0);
    let state: string | null = null;
    let most = unknown;
    for (const [name, share] of Object.entries(covered)) {
      const rank = STRETCH_RANK[name] ?? 0;
      const held = state === null ? 0 : STRETCH_RANK[state] ?? 0;
      if (share > most || (share === most && rank > held)) {
        state = name;
        most = share;
      }
    }
    const look = stretchLook(state);
    parts.push(text({ ...look.props, ...(dim ? { dimColor: true } : {}) }, look.glyph));
  }
  return box({ flexDirection: "row", gap: 0 }, parts);
}

/**
 * A rate bar across the width it was given.
 *
 * The filled part carries the run's own color and the rest is drawn quiet, so a
 * share is read at a glance. Two things draw no bar at all, and both return null:
 * a run with no denominator to divide by, because an empty track under it reads
 * as nought done rather than as nothing known, and a run whose counts cannot
 * both be true, because a bar is the one thing on the pane that shows progress
 * as a proportion and a proportion of an impossible pair means nothing. What a
 * row does instead is state the two numbers and let them be read.
 */
export function rateBar(done: number, total: number, color: Color | undefined,
                        width: number): Node | null {
  if (!(total > 0) || !Number.isFinite(done) || !Number.isFinite(total)) {
    return null;
  }
  if (done < 0 || done > total) {
    return null;
  }
  // The width is the length the caller declared, and nothing else: overriding it
  // with a minimum of four drew a four-cell bar for a setting that asked for
  // two. A length of no cells is no bar at all rather than a bar of one, because
  // a single filled cell is a claim about a proportion nothing was measured for.
  const cells = Math.floor(width);
  if (cells < 1) {
    return null;
  }
  const filled = Math.max(0, Math.min(cells, Math.round((done / total) * cells)));
  const parts: Node[] = [];
  if (filled > 0) {
    parts.push(text({ color: color ?? "success" }, BAR_FILLED.repeat(filled)));
  }
  if (filled < cells) {
    parts.push(text({ dimColor: true }, BAR_TRACK.repeat(cells - filled)));
  }
  if (!parts.length) {
    return null;
  }
  const drawn = box({ flexDirection: "row", gap: 0 }, parts);
  const vector = barVector(done, total, color ?? "success", cells);
  return vector ? { ...drawn, vector } : drawn;
}

